(window.__BOOKS=window.__BOOKS||{})["e_phoenissae"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"iokasta\">Иокаста</span></span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Старик</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"antigona\">Антигона</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Хор</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"polinik\">Полиник</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"eteokl\">Этеокл</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"kreont\">Креонт</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Тиресий</span> <span class=\"act-no\">(I)</span> . При нем дочь Манто"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"menekey\">Менекей</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Вестник</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Другой вестник</span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"edip\">Эдип</span></span> <span class=\"act-no\">(I)</span>"],["place","Действие происходит в Кадмее перед дворцом Лабдакидов. Дворец имеет на крыше род балкона. Перед дворцом находится алтарь Аполлона — гения улиц (Agyieus). У Иокасты черный пеплос и обрезанные седые волосы. Она опирается на посох, который бросает при виде сына. Тиресий носит обычную сетчатую одежду предсказателей и на голове золотой венок. У Антигоны фата и шафранный пеплос. Хор состоит из 15 молодых и красивых девушек семитического типа."],["act","Пролог","a1",""],["scene","Явление первое","s1",1,1],["sd","Из ворот дворца выходит <span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>. Закат солнца."],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","О Гелиос, среди небесных звезд",0,1,0,0],["v","Просекший путь для кобылиц летучих",0,1,0,0],["v","И золотом горящей колесницы!",0,1,0,0],["v","Печальные, недобрые лучи<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,2,0,0],["v","Агенориду Кадму посылал ты",0,3,0,0],["v","В тот день, когда на эту землю он",0,4,0,0],["v","Вступил, брега покинув Финикии…",0,5,0,0],["v","Киприды дочь, Гармонию, поял",0,6,0,0],["v","Здесь в жены он, и сына Полидора",0,7,0,0],["v","Он с ней родил. Был внуком их Лабдак",0,8,0,0],["v","И правнуком покойный муж мой Лаий,",0,9,0,0],["v","Мне ж был отцом могучий <span class=\"ch\" data-ch=\"menekey\">Менекей</span>,",0,10,0,1],["v","И мать одна носила нас с <span class=\"ch\" data-ch=\"kreont\">Креонтом</span>.",0,10,0,0],["v","<span class=\"ch\" data-ch=\"iokasta\">Иокастою</span> отец меня нарек",0,11,0,0],["v","И Лабдакиду в жены отдал Лаию…",0,12,0,0],["v","Сначала был бесплоден наш союз, —",0,13,0,0],["v","Но вот молить о сыне Аполлона",0,14,0,0],["v","В дельфийский храм отправился мой муж, —",0,15,0,0],["v","И так вещал оракул: \"Царь фиванский,",0,16,0,0],["v","Наперекор богам, ты не желай",0,17,0,0],["v","Жене детей, — родивши с нею сына,",0,18,0,0],["v","Убийцу, Лай, родишь ты своего —",0,19,0,0],["v","И весь за ним твой царский род погибнет\".",0,20,0,1],["v","Увы! Зажжен вином, в веселый час",0,20,0,0],["v","Забылся муж…",0,21,0,0],["v","Родился сын. И вот, богам послушный,",0,22,0,0],["v","<em>Стопы ему пронзив железом острым</em>,",0,23,0,0],["v","Рабам его велит снести отец",0,24,0,0],["v","На дальние утесы Киферона,",0,25,0,0],["v","В те Герою почтенные луга…",0,26,0,0],["v","Табунщики там отыскали сына,<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,27,0,0],["v","И, во дворец Полибов отнесен,",0,28,0,0],["v","Царицею был принят мой ребенок…",0,29,0,0],["v","Она, к груди ребенка приложив,",0,30,0,1],["v","Державного супруга убедила,",0,30,0,0],["v","Что этот мной рожденный в муках сын",0,31,0,0],["v","Произошел на свет от их союза.",0,31,0,0],["v","Но годы шли. Уж золотой пушок",0,32,1,0],["v","Вдоль щек пошел Эдиповых, и мужем",0,33,0,0],["v","Он сделался. Тут, догадался ль сам",0,33,0,0],["v","Иль от людей проведал, что приемыш,",0,34,0,0],["v","Но только вдруг он в Дельфы заспешил:",0,35,0,0],["v","Пусть бог отца и мать ему откроет…",0,35,0,0],["v","В те злые дни и мой покойный Лай",0,36,0,0],["v","К оракулу поехал: захотелось",0,36,0,0],["v","Царю узнать от Феба, жив ли сын,",0,37,0,0],["v","Им брошенный. Отец и сын столкнулись",0,38,0,0],["v","В Фокиде, на распутий, — и сыну",0,38,0,0],["v","Надменный так возница закричал:",0,39,0,0],["v","\"Посторонись, прохожий! Дай дорогу —",0,40,0,1],["v","Царю проехать негде\". Но <span class=\"ch\" data-ch=\"edip\">Эдип</span>",0,40,0,0],["v","По-прежнему шел гордо и ни слова",0,41,0,0],["v","Не отвечал вознице… Тот коней",0,41,0,0],["v","Не стал удерживать. И кровью обливает",0,42,0,0],["v","Идущему ступни железный шаг.",0,43,0,0],["v","О… повторять ли мне, что было дальше?..",0,43,0,0],["v","Припоминать, как сын убил отца,<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,44,0,0],["v","Как, завладев запряжкою, Полибу",0,45,0,0],["v","Ее отвез, кормильцу своему?..",0,45,0,0],["v","Настали следом тяжкие невзгоды:",0,46,0,0],["v","Бог весть отколь на Фивы налетев,",0,46,0,0],["v","Коварная душила граждан дева…",0,47,0,0],["v","Вдовою я была, и брат <span class=\"ch\" data-ch=\"kreont\">Креонт</span>",0,48,0,0],["v","В награду ложе царское назначил",0,48,0,0],["v","Отгадчику мудреных девьих слов…",0,49,0,0],["v","Их отгадать… увы, пришлось <span class=\"ch\" data-ch=\"edip\">Эдипу</span>…",0,50,0,1],["v","И вот, прияв фиванский трон и власть,",0,50,1,0],["v","На матери женился сын несчастный;",0,51,0,0],["v","Не зная сам, с незнающей делил",0,52,0,0],["v","Он ложе брачное. Да, от <span class=\"ch\" data-ch=\"edip\">Эдипа</span>",0,53,0,0],["v","Двух сыновей имею — <span class=\"ch\" data-ch=\"eteokl\">Этеокла</span>",0,54,0,0],["v","И <span class=\"ch\" data-ch=\"polinik\">Полиника</span> славного, и двух",0,55,0,0],["v","Я дочерей с ним прижила — меньшую",0,56,0,0],["v","Исменою нарек ее отец,",0,57,0,0],["v","А старшую зову я <span class=\"ch\" data-ch=\"antigona\">Антигоной</span>.",0,58,0,0],["v","Когда в жене своей <span class=\"ch\" data-ch=\"edip\">Эдип</span> узнал",0,59,0,0],["v","Родную мать, он, ужасом сознанья",0,60,0,1],["v","И муками истерзанный, казнил",0,60,0,0],["v","Свои глаза, и золотые пряжки",0,61,0,0],["v","Вмиг кровью глаз потухших облились…",0,62,0,0],["v","А сыновья, едва их подбородки",0,62,0,0],["v","Пух юности заносчивой покрыл,",0,63,0,0],["v","Отца в затвор отправили, — забвеньем",0,64,0,0],["v","Они беду надеялись покрыть…",0,65,0,0],["v","Он жив еще и здесь. И хоть судьба",0,65,0,0],["v","Виной его несчастий, а не дети,",0,66,0,0],["v","На сыновей из нечестивых уст",0,67,0,0],["v","Он изрыгнул ужасные проклятья.",0,67,0,0],["v","Он пожелал, чтоб острие меча",0,68,1,0],["v","Меж ними дом отцовский поделило…",0,69,0,0],["v","И сыновья, его страшася слов,",0,70,0,1],["v","Расстаться порешили полюбовно…",0,70,0,0],["v","На вольное изгнанье <span class=\"ch\" data-ch=\"polinik\">Полиник</span>",0,71,0,0],["v","Себя немедля осудил, как младший.",0,72,0,0],["v","\"Пусть, — он сказал, — мой старший первый год",0,72,0,0],["v","Над Фивами царит\". А тот, кормило",0,73,0,0],["v","В руках почувствовав, не захотел",0,74,0,0],["v","В урочный час расстаться с царским троном",0,75,0,0],["v","И через год насилием прогнал",0,75,0,0],["v","Соперника и брата. <span class=\"ch\" data-ch=\"polinik\">Полиник</span>",0,76,0,0],["v","Отправился в Микены, от Адраста",0,77,0,0],["v","Царевну-дочь там в жены получил,",0,77,0,0],["v","И вот, собрав аргосские дружины,<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,78,0,0],["v","Он здесь теперь, у семивратных стен,",0,79,0,0],["v","И требует фиванского престола.",0,80,0,1],["v","Меж сыновей неистовый раздор",0,80,0,0],["v","Я прекратить должна и настояла,",0,81,0,0],["v","Чтоб раньше, чем на бой сходиться им,",0,82,0,0],["v","Здесь <span class=\"ch\" data-ch=\"polinik\">Полиник</span> был принят. Мой посол",0,82,0,0],["v","Вернулся, а царевич будет следом…",0,83,0,0],["v","Тебя молю, живущий в небесах",0,84,1,0],["v","За волнами лазурного сиянья,",0,84,0,0],["v","Спаси нас, Зевс, и помири детей!",0,85,0,0],["v","О, мудрый бог, всю жизнь одних и тех же",0,86,0,0],["v","Ты иго бед носить не осуждай…",0,86,0,0],["sd","(Уходит во дворец.)"],["scene","Явление второе","s2",1,2],["v","Старый раб на вышке дворца. Потом <span class=\"ch\" data-ch=\"antigona\">Антигона</span>.<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,87,0,0],["sp","Старик"],["dir","глядя вниз, на выход из внутренней дворцовой лестницы"],["v","О, слава дома отчего и гордость,",0,88,1,0],["v","Царевна <span class=\"ch\" data-ch=\"antigona\">Антигона</span>! В терему",0,88,0,0],["v","Девице скучно, видно: упросила",0,89,0,0],["v","Царицу-мать, чтобы тебя она",0,90,0,1],["v","Пустила на аргосцев подивиться…",0,90,0,0],["v","Но погоди, дай кинуть взор окрест:",0,91,1,0],["v","Из граждан кто не смотрит ли на крышу…",0,92,0,0],["v","Сейчас раба седого упрекнут,",0,93,0,0],["v","Да и тебя, царевну молодую…",0,94,0,0],["v","Все, госпожа, тебе я передам,",0,95,1,0],["v","Что мне узнать пришлося да увидеть,",0,96,0,0],["v","Пока во вражий лагерь я ходил",0,97,0,0],["v","И нес сюда, обратно, клятвы мира…",0,98,0,0],["sd","(Смотрит по сторонам.)"],["v","Нет… никого… Спокойно можешь ты",0,99,0,0],["v","По лестнице кедровой и старинной",0,100,0,1],["v","На наш дворец подняться, Антигона…",0,100,0,0],["v","Чт<em>о</em> войска-то аргосского сошлось!..",0,101,0,0],["v","Куда ни глянешь: в поле ль, на прибрежье ль",0,102,0,0],["v","Исмена светлого или Диркеи нашей…<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,103,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","ее еще не видно"],["v","Протяни мне старую руку,",0,104,0,0],["v","Помоги мне, старик, подняться…",0,105,0,0],["v","Круты мне, молодой, ступени.",0,105,0,0],["sp","Старик"],["v","Держись, дитя! Ты подоспела кстати…",0,106,0,0],["sd","(Поднимает <span class=\"ch\" data-ch=\"antigona\">Антигону</span>.)"],["v","Смотри: движенье началось какое,",0,107,0,0],["v","В каком порядке строятся аргосцы…",0,108,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","оглядывается, потом несколько секунд молча смотрит вдаль, затем всплескивает руками"],["v","О богиня! О дочь Латоны!",0,109,0,0],["v","О святая Геката!",0,110,1,1],["v","Сколько меди там ярко блестящей:",0,110,0,0],["v","Словно молнии в поле блещут.",0,111,0,0],["sd","(Закрывает лицо руками.)"],["sp","Старик"],["dir","любуясь на лагерь и улыбаясь"],["v","Да, <span class=\"ch\" data-ch=\"polinik\">Полиник</span> пришел не как-нибудь!",0,112,0,0],["v","Чт<em>о</em> колесниц! Чт<em>о</em> воинов! А к<em>о</em>ней?",0,112,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","оборачивается и, прижимаясь к старику, схватывает его за руку"],["v","На воротах засовы-то медные,",0,113,1,0],["v","Они крепко ли, старый, задвинуты?",0,114,1,0],["v","Ворот<em>а</em>-то в стенах амфионовых,",0,115,1,0],["v","В белокаменных стенах не ходят ли?",0,115,0,0],["sp","Старик"],["dir","успокоительно гладит ее руку"],["v","Не бойся: стен фиванских не возьмут.",0,116,0,0],["v","Но разве ты не хочешь подивиться",0,117,0,0],["v","На воинов, дитя мое, царевна?",0,117,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","снова оборачивается к лагерю, потом с живостью"],["v","Ах! Кто это, кто?",0,118,0,0],["v","С белым султаном,",0,119,0,0],["v","Перед дружинами?",0,120,0,1],["v","Видишь, старик?",0,120,0,0],["v","Щит на руке его",0,121,0,0],["v","Так и горит луной,",0,122,0,0],["v","Так вот и ходит весь…",0,122,0,0],["sp","Старик"],["v","Начальник, госпожа.<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,123,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Откуда родом?",1,123,0,0],["v","Как именем зовется, все скажи.",0,124,0,0],["sp","Старик"],["v","Микенец он, моя царевна, в Лерне",0,125,0,0],["v","Его дворец: он — царь Гиппомедонт.",0,125,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Боги мои! Грозный какой:<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,126,1,0],["v","Ужас возьмет, как поглядишь!",0,127,1,0],["v","Людям не сроден он:",0,127,1,0],["v","Он на гиганта,",0,128,1,0],["v","Сына Земли, похож, точно Стероп<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,129,1,0],["v","С вазы расписанной… Ну, а другой?",0,130,0,1],["v","Видишь: Диркею переезжает он:",0,130,0,0],["v","Странно одет он так, вооружен?",0,131,0,0],["v","Кто он, старик?",0,132,0,0],["sp","Старик"],["v","Он по отцу Ойнеевич, а панцирь",0,133,0,0],["v","На нем надет, царевна, этолийский.",0,133,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Так вот это кто!<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,134,0,0],["v","Они с <span class=\"ch\" data-ch=\"polinik\">Полиником</span>",0,135,0,0],["v","Женаты на сестрах родных…<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,136,0,0],["v","О боги… какой же он странный!..",0,136,0,0],["v","Ты варвара подмесь сейчас отличишь",0,137,0,0],["v","В обличье его и доспехах…",0,138,0,0],["sp","Старик"],["v","Щиты у всех такие этолийцев,",0,139,0,0],["v","И все они — чудесные стрелки…",0,140,0,1],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","⟨А ты, старик, откуда это знаешь?",0,141,0,0],["sp","Старик"],["v","Я вижу на щитах изображенья:",0,142,0,0],["v","Взглянув на них, я узнаю вождей.⟩",0,143,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","А возле гроба Зетова… Ты видишь?",0,144,0,0],["v","Вон в локонах и так сердито смотрит,",0,145,0,0],["v","По виду юноша, — а между тем за ним,",0,146,0,0],["v","Как за начальником, идет толпа густая",0,147,0,0],["v","Во всеоружии.",0,148,0,0],["sp","Старик"],["v","Парфенопей",1,148,0,0],["v","Его зовут, рожденный Аталантой…<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,150,0,1],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Он сын Аталанты —",0,150,2,0],["v","Но пусть о подруге забыв и спутнице верной",0,151,0,0],["v","Веселых охот,",0,151,2,0],["v","О, пусть Артемида его",0,152,1,0],["v","За этот набег покарает",0,153,1,0],["v","И легкой стрелою смирит!",0,153,1,0],["sp","Старик"],["v","Все так, дитя. Но привела их правда.",0,154,0,0],["v","Не просмотреть бы этого богам.<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,155,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","быстро бегая взором по лагерю"],["v","Но где ж он, скажи мне?",0,155,0,0],["v","Где брат <span class=\"ch\" data-ch=\"polinik\">Полиник</span> мой, с которым",0,156,0,0],["v","Одна нас, старик,",0,156,1,0],["v","Несчастная мать породила?",0,157,0,0],["v","Очам моим жадным скорей",0,158,1,0],["v","Открой моего <span class=\"ch\" data-ch=\"polinik\">Полиника</span>!",0,158,1,0],["sp","Старик"],["v","Да вот, царевна, около могилы",0,159,0,0],["v","Семи убитых Ниобид, с Адрастом<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,160,0,1],["v","Он говорит. Ты видишь ли?",0,160,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","всматривается"],["v","Едва…",1,160,0,0],["v","Я различить могу лишь очертанья",0,161,3,0],["v","Его фигуры. Бледный очерк груди…",0,162,3,0],["sd","(Всматривается, потом с загоревшимися глазами.)"],["v","О, если бы, как облако, могла я",0,163,4,0],["v","По воздуху к изгнаннику примчаться",0,164,4,0],["v","И, шею милую руками обвивая,",0,165,4,0],["v","К его груди покинутой прижаться!",0,166,4,0],["sd","(Берет старика за руку.)"],["v","Скажи, старик! Не правда ль, он прекрасен,",0,167,4,0],["v","В своих доспехах ярких, как лучи",0,168,4,0],["v","Румяного, проснувшегося солнца?",0,169,4,0],["sp","Старик"],["v","Тебе на радость, госпожа, придет",0,170,0,1],["v","Сюда твой <span class=\"ch\" data-ch=\"polinik\">Полиник</span> сегодня…",0,170,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Этот",1,170,0,0],["v","Скажи мне, кто? вот видишь, взял он вожжи..",0,171,0,0],["v","Запряжка белая… Ты видишь?",0,172,0,0],["sp","Старик"],["v","Это жрец, —",1,172,0,0],["v","Амфиарай-гадатель, — неразлучна<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,172,0,0],["v","С ним жертвы кровь — отрада почвы жадной.",0,173,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","всплескивает руками"],["v","Дочь Латоны Светлоопоясанной,",0,174,1,0],["v","Артемида моя Златолунная!<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,175,1,0],["v","О, как он легко и красиво",0,175,2,0],["v","Коней своих бешеных правит,",0,176,2,0],["v","И колет, и дразнит спокойно!..",0,177,2,0],["v","А где же, скажи мне, надменный",0,177,2,0],["v","Где царь Капаней,",0,178,3,0],["v","С его угрозою дерзкой?",0,179,0,0],["sp","Старик"],["v","Да вот он: стены мерит вверх да вниз,",0,180,0,1],["v","Где б лестницу приставить, выбирает.",0,180,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Боги бессмертные,",0,181,2,0],["v","Дева отмщения,",0,182,2,0],["v","Громы Зевесовы тяжкие,",0,182,2,0],["v","Молний его",0,183,2,0],["v","Пламя палящее!",0,184,2,0],["v","Я заклинаю вас:",0,185,2,0],["v","Гордость безмерную",0,185,2,0],["v","Вы успокойте…",0,186,2,0],["v","Он обещался копьем",0,187,0,0],["v","Пленниц фиванских добыть:",0,187,0,0],["v","Лерне, Микенам своим",0,188,0,0],["v","Вдоволь рабынь насулил.<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a><a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,189,0,0],["v","О Артемида, о ты, златокудрое чадо Зевесово,",0,190,0,1],["v","О, не давай меня на поругание, в рабство постылое!",0,191,0,0],["sp","Старик"],["dir","касаясь ее плеча"],["v","Уж время, дочь моя, сойди опять",0,192,0,0],["v","Под отчий кров и в свой девичий терем",0,193,0,0],["v","За ткацкий стан безропотно вернись:",0,194,0,0],["v","Ты в сердце жар желаний утолила,",0,195,0,0],["v","Все видела, царевна… А теперь",0,196,0,0],["v","Перед дворцом толпятся наши гостьи…",0,197,0,0],["v","Не попадай к подругам на язык.",0,198,0,0],["v","Ведь женщины всегда прибавить рады;",0,199,0,0],["v","И их уста злоречия полны,",0,200,0,1],["v","Когда они одна другую судят.",0,200,0,0],["sd","Уходят по внутренней лестнице: раб впереди и снимает <span class=\"ch\" data-ch=\"antigona\">Антигону</span> с крыши. Между ними перед дворцом показывается хор молодых девушек в пестрых одеждах. Большая часть черноволосых, с матовым овалом лица. Корифей — девушка высокого роста и мужского типа."],["scene","Парод","s3",1,3],["sd","Пение сопровождается медленными мимическими движениями."],["sp","Хор"],["str","Строфа I"],["v","Тирийские волны, простите навек!",0,201,0,0],["v","Прости, мой остров родимый!<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,202,1,0],["v","Недолго на воле сияла краса, —",0,203,0,0],["v","И горькой я стала рабыней.<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,204,1,0],["v","И на склоны, венчанные снегом,",0,205,0,0],["v","К Парнасу иду я печально,",0,205,1,0],["v","В чертог Аполлона влекома…",0,206,1,0],["v","Мне звучало",0,207,0,0],["v","музыкой сладкой",1,207,0,0],["v","В парусах",0,208,0,0],["v","дыханье зефира,",1,208,0,0],["v","Когда ионийские волны",0,209,0,0],["v","Тирийская ель рассекала",0,210,0,1],["v","И мимо меня пробегали",0,211,0,0],["v","Сицилии влажные нивы.<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,212,0,0],["str","Антистрофа I"],["v","Так боги велели, чтоб в Тире моем",0,213,0,0],["v","Для Феба я расцветала,",0,214,1,0],["v","Но сердцу мой жребий почетный не мил.",0,215,0,0],["v","Увы мне! Под стенами Кадма,",0,216,1,0],["v","У потомков царя Агенора,",0,217,0,0],["v","Тирийского царского рода,",0,218,1,0],["v","Я только рабыня, подруги.",0,219,1,0],["v","Я теперь —",0,220,0,1],["v","золотая статуя,",1,220,0,0],["v","Я — красивый",0,220,0,0],["v","дар Аполлону, —",1,220,0,0],["v","И ждут Кастальские воды",0,221,0,0],["v","Омыть волной благодатной",0,222,0,0],["v","У Фебовой девы-рабыни",0,223,0,0],["v","Ее шелковистые косы.",0,224,0,0],["str","Эпод"],["v","О блестящие скалы Парнаса,",0,225,0,0],["v","И ты, о светлая высь его двуглавой вершины,",0,226,0,0],["v","Где факелы пляски священной",0,227,0,0],["v","Царя Диониса мелькают!",0,228,0,0],["v","О вечно цветущая лоза,",0,229,1,0],["v","Точащая сок виноградный",0,230,1,1],["v","В бессменно обильные кисти!",0,230,1,0],["v","Дракона божественный грот,<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,231,1,0],["v","И ты, ущелие Феба,",0,232,1,0],["v","И вы, священные склоны,",0,233,1,0],["v","Венчанные снегом!..",0,233,1,0],["v","Примите меня, рабыню,",0,234,0,0],["v","Когда я Диркею покину,",0,235,0,0],["v","И пусть,",0,236,0,0],["v","вплетясь в хороводы",1,236,0,0],["v","Светлой",0,236,0,0],["v","девы-богини,",1,236,0,0],["v","Я пред жерлом священным<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,237,1,0],["v","Бледного страха не знаю.",0,238,1,0],["str","Строфа II"],["v","Кровавый сигнал пылает!",0,239,0,0],["v","И бурю и смерть",0,240,1,1],["v","Уж сеет Арей",0,240,1,0],["v","На нивы Кадмеи,",0,241,0,0],["v","Но вы, о другие, от Фив",0,242,0,0],["v","Губительный бой удалите!..",0,242,0,0],["v","Мы горе друзей",0,243,1,0],["v","И беды свои",0,244,1,0],["v","Не знаем делить…",0,245,1,0],["v","И стоны с башен фиванских",0,245,0,0],["v","Слезой в Финикии прольются.",0,246,0,0],["v","Недаром и кровь и дети",0,247,1,0],["v","Одни, что в Кадмее, что в Тире,",0,247,1,0],["v","И корень недаром один — рогатая Ио!",0,248,0,0],["v","Мне так вас жаль, Лабдакиды!",0,249,1,0],["str","Антистрофа II"],["v","Уж в воздухе кровью запахло,",0,250,1,1],["v","И тучей густой",0,250,1,0],["v","Повисли щиты",0,251,1,0],["v","Близ башен фиванских…",0,252,0,0],["v","Но в лязге мечей боевых",0,252,0,0],["v","Поймут ли, скажи, Лабдакиды,",0,253,0,0],["v","Что братская их",0,254,1,0],["v","Эриний рукой",0,255,1,0],["v","Вражда зажжена?..<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,255,1,0],["v","Боюсь тебя, для Кадмеи",0,256,0,0],["v","Аргосцев страшное войско,",0,257,0,0],["v","Но больше страшит мне сердце,",0,257,1,0],["v","Что боги стоят за Аргос,",0,258,1,0],["v","Что меч <span class=\"ch\" data-ch=\"polinik\">Полинику</span>-царю в походе на Фивы",0,259,0,0],["v","Точила вечная правда.<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,260,1,1],["sd","Во время последней части хоровой песни набегает мрак. В небе со стороны аргосского лагеря поднимается розовое зарево костров."],["act","Действие первое","a2","I"],["scene","Явление третье","s4",2,4],["sd","Входит <span class=\"ch\" data-ch=\"polinik\">Полиник</span>. Он идет крадучись, озираясь, и в руке у него длинный меч."],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["dir","издали"],["v","Там в воротах тяжелые засовы",0,260,0,0],["v","Раздвинулись, и стража так свободно",0,261,0,0],["v","Меня впустила в город. Но тревоги",0,262,0,0],["v","Я побороть не в силах… Нет ли тут",0,263,0,0],["v","Сетей каких — захватят и изранят…",0,263,0,0],["v","Пусть зоркий взгляд обходит не спеша",0,264,0,0],["v","Места окрестные… Ужель коварство",0,265,0,0],["v","Тут кроется?..",0,266,0,0],["sd","(Обнажает меч.)"],["v","О, этот острый меч",0,266,4,0],["v","Мне бодрости прибавит… Тише, тише…",0,267,0,0],["sd","(Останавливается.)"],["v","Какой-то шум! Постойте! Кто там ходит?",0,268,0,0],["v","Нет, кажется, почудилось… Пока",0,269,0,0],["v","Опасность есть, и призрак нас пугает…",0,270,0,1],["v","Среди врагов особенно, и мать,",0,270,0,0],["v","Хотя меня прийти уговорила,",0,271,0,0],["v","Разубедить, конечно, не могла…",0,272,0,0],["sd","(Оборачивается и видит алтарь.)"],["v","А вот она — защита — наш алтарь:",0,272,0,0],["v","У алтаря очаг дымится… Только",0,273,0,0],["v","Перед дворцом какие-то фигуры…",0,274,0,0],["sd","(Шепотом и протягивая вперед меч.)"],["v","На всякий случай меч перед собой",0,275,0,0],["v","Я протяну во мраке.",0,275,0,0],["sd","(Быстро прячет меч.)"],["v","Это жены…",0,276,4,0],["v","Спросить их, кто они?",0,277,0,0],["sd","(Обращаясь к хору.)"],["v","О чужеземки!",0,277,4,0],["v","Где ваша родина и в этот царский дом,",0,278,0,0],["v","В Элладу, как попали вы, скажите!",0,279,0,0],["sp","Корифей"],["v","В Фин<em>и</em>кии я родилась, и в Тире",0,280,0,1],["v","Я расцвела. Тирийские цари",0,280,0,0],["v","Рабынею меня послали к Фебу,",0,281,0,0],["v","За то, что бог победой их венчал…",0,282,0,0],["v","А здесь, когда <span class=\"ch\" data-ch=\"edip\">Эдипа</span> сын собрался",0,283,0,0],["v","Направить дар в Фокиду, к очагу",0,283,0,0],["v","Преславного дельфийского владыки,",0,284,0,0],["v","Ограду Фив аргосец осадил…",0,285,0,0],["v","Но ты скажи, откуда ты, пришелец,",0,286,0,0],["v","⟨<em>Сюда явился в семивратный град?</em>⟩",0,286,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Сын Лаия, о жены, зародил,",0,287,0,0],["v","И дочь меня носила <span class=\"ch\" data-ch=\"menekey\">Менекея</span>,",0,288,0,0],["v","По имени <span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>, а зовут",0,289,0,0],["v","Меня мои фиванцы <span class=\"ch\" data-ch=\"polinik\">Полиником</span>.",0,290,0,1],["sp","Корифей"],["v","Ты — наш! одна в Агеноридах кровь,",0,290,0,0],["v","Она с царями Тира дорогого",0,291,0,0],["v","Тебя роднит, державный <span class=\"ch\" data-ch=\"polinik\">Полиник</span>…",0,292,0,0],["v","Выходит луна, и делается светло как днем.",0,292,0,0],["sd","(Бросаясь к ногам Политика.)"],["v","Свой я закон храню:<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,293,2,0],["v","К светлым стопам твоим",0,294,2,0],["v","Я припадаю, царь.",0,295,2,0],["v","⟨<em>В отчей ты вновь земле.</em>⟩",0,295,2,0],["sd","(Потом обращается к дворцу.)"],["v","Ио! Ио!",0,296,0,0],["v","О госпожа, иди скорей и настежь",0,297,0,0],["v","Дверь распахни для сына! Неужели",0,297,0,0],["v","Не чует сердце матери? Что медлишь",0,298,0,0],["v","Покинуть сень чертога и обнять",0,299,0,0],["v","Свое дитя дрожащими руками?",0,300,0,1],["scene","Явление четвертое","s5",2,5],["sd","Те же и <span class=\"ch\" data-ch=\"iokasta\">Иокаста</span> — идет, опираясь на посох, в черной одежде и простоволосая."],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","На ваш призыв, о гости Финикии,",0,300,0,0],["v","Спешила я, и посохом дрожащий",0,301,0,0],["v","Прямился мой, давно неверный, шаг…",0,302,0,0],["sd","(Видит <span class=\"ch\" data-ch=\"polinik\">Полиника</span>, делает шаг к нему и, бросив посох, протягивает перед собою обе руки.)"],["v","Мое дитя любимое!",0,303,0,0],["v","<span class=\"ch\" data-ch=\"polinik\">Полиник</span> подходит к ней.",0,304,0,0],["sd","(Она берет его за плечи и несколько секунд всматривается в его лицо.)"],["v","О, сколько дней, о, сколько долгих дней",0,305,2,0],["v","Я светом глаз твоих не любовалась!",0,305,2,0],["sd","(Открывает на груди пеплос.)"],["v","Обними, Полиник, ты кормилицу-грудь",0,306,3,0],["v","И, щекою к лицу прижимаясь,",0,307,3,0],["v","Темнокудрой волною волос",0,308,3,0],["v","Шею матери нежно обвей.",0,309,3,0],["v","Ты — со мной… Я так долго ждала,",0,310,3,1],["v","Я сгорала тоской и надеждой…",0,310,3,0],["v","И гляжу на тебя и не верю,",0,311,3,0],["v","Что со мной ты опять, дитя,",0,312,3,0],["v","Все слова свои мать растеряла",0,313,3,0],["v","За томление долгой разлуки.",0,314,3,0],["v","Я стою и сама не знаю,",0,315,3,0],["v","Обнимать ли тебя мне сладко",0,315,3,0],["v","Или в пляске пойти кружиться…",0,316,3,0],["sd","(Долго молча ласкает <span class=\"ch\" data-ch=\"polinik\">Полиника</span>.)"],["v","О Полиник,",0,317,4,0],["v","В доме отцовском",0,318,4,0],["v","Как без тебя пусто казалось нам,",0,319,3,0],["v","Сколько ты слез друзьям,",0,320,4,1],["v","Сколько ты гражданам",0,320,4,0],["v","Горьких оставил слез,",0,321,4,0],["v","А <span class=\"ch\" data-ch=\"eteokl\">Этеокла</span> единокровного",0,321,4,0],["v","Как укоряли мы!..",0,322,4,0],["v","Я волны волос поседевших с тех пор распустила,",0,322,0,0],["v","И их серебристые пряди в печали скосило железо,",0,323,0,0],["v","И белого цвета в одежде я больше не знаю,",0,323,0,0],["v","Но часто с тех пор",0,324,4,0],["v","По черным и ветхим лохмотьям,",0,324,3,0],["v","На теле повисшим,",0,325,3,0],["v","Текут материнские слезы.",0,325,3,0],["v","[О сын мой любимый и горький!]",0,326,3,0],["v","А старый слепец",0,326,4,0],["v","В чертоге отцовском,",0,327,4,0],["v","О, если бы знал ты:",0,327,4,0],["v","С той самой поры,",0,328,4,0],["v","Как ты от ярма",0,328,4,0],["v","Из пары ушел,",0,329,4,0],["v","Покоя несчастный не знает, со вздохами слезы мешая,",0,330,0,1],["v","Зарезаться он порывался,<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,331,3,0],["v","Из петли его вынимали;",0,332,3,0],["v","И все среди стонов проклятья свои выкликает,",0,333,0,0],["v","И мрак наполняют тяжелые вопли слепого…",0,334,0,0],["v","Женился ты, сын мой?",0,335,3,0],["v","Скажи, что неправда!",0,336,3,0],["v","Неужто ж действительно ты на чужбине женился?!",0,340,0,1],["v","О, горе родившей тебя!",0,340,3,0],["v","Для древнего Лаия обида",0,341,3,0],["v","И грех тебе, грех, Полиник,",0,342,3,0],["v","Что в дом ты ведешь чужеземку!",0,343,3,0],["v","Блаженства лишенная мать, не я зажигала — увы! —",0,344,0,0],["v","Твой свадебный факел.",0,345,3,0],["v","Ласкающей влагой Исмена родимого волны",0,346,0,0],["v","Для брачного ложа, о сын мой, тебя не омыли,",0,347,0,0],["v","И улицы Фив не звучали от свадебных гимнов,",0,348,0,0],["v","Встречая царевну…",0,349,3,0],["v","Ты, бедствий источник сокрытый, иссякни во мраке!",0,350,0,1],["v","Война или распря нас губит,",0,350,3,0],["v","Отца ль твоего преступленье,",0,351,3,0],["v","Иль демон жестокий и черный в чертогах",0,352,0,0],["v","<span class=\"ch\" data-ch=\"edip\">Эдипа</span> пирует…",0,352,3,0],["v","О, кто б ни посеял вас, беды, вы сердце мое истерзали.,",0,353,0,0],["sp","Корифей"],["v","Что значит муки вытерпеть, рождая:",0,354,0,0],["v","Не может мать ребенка не любить.",0,355,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Родимая!.. Я прав, и я — безумец,",0,355,0,0],["v","Безумец, да… Разумный не пойдет",0,356,0,0],["v","Один к врагам и в осажденный город,",0,357,0,0],["v","Но этот город — дом мой, и я прав…",0,357,0,0],["v","Да, мать моя, влечения к отчизне",0,358,0,0],["v","Преодолеть не может человек:",0,359,0,0],["v","Слова тебе докажут что угодно,",0,360,0,1],["v","Но истина сильнее всяких слов.",0,360,0,0],["v","Я шел сюда… все время опасаясь",0,361,0,0],["v","Сетей врагов, и, тяжкий вынув меч,",0,362,0,0],["v","Перед собой держал его, а очи",0,363,0,0],["v","Тревожно мрак окрестный озирали.",0,363,0,0],["v","И если уцелел я, это ты",0,364,0,0],["v","Меня спасла своей священной клятвой…",0,365,0,0],["sd","(Оглядывается.)"],["v","О, только ты… Да, вот он, наш чертог.",0,366,0,0],["v","Вот и алтарь, — опять открылись взорам",0,366,0,0],["v","Гимнасии, где рос я, и родной",0,367,0,0],["v","Диркеи блеск… я рад, а слезы льются<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,368,0,0],["v","Из глаз моих… О милые места!",0,369,0,0],["v","От вас я был отторгнут так жестоко,",0,370,0,1],["v","В чужой земле на слезы осужден,",0,370,0,0],["v","Но вас опять увидел я — и плачу…",0,371,0,0],["sd","(Плачет.)"],["v","Но ты, о мать моя! О, горький вид",0,372,0,0],["v","Обрезанных волос, одежды черной!",0,372,0,0],["v","Как ты бедой измучена моей!",0,373,0,0],["v","О, что за бич вражда единокровных,",0,374,0,0],["v","⟨Когда им больше примиренья нет!",0,375,0,0],["v","А что отец, во мраке вечной ночи",0,375,0,0],["v","Живущий здесь? Что две сестры мои?",0,376,0,0],["v","Все плачут ли о беглеце невольном?⟩",0,377,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","<span class=\"ch\" data-ch=\"edip\">Эдипов</span> род могучею рукой",0,377,0,0],["v","На казнь влечет один из олимпийцев:",0,378,0,0],["v","А корень зол — зачатья тяжкий грех,",0,379,0,0],["v","Отцовский брак и ты, в грехе рожденный.",0,380,0,1],["v","Но для чего все это? Так богам",0,380,0,0],["v","Угодно было, — и довольно…",0,381,0,0],["v","Сын мой!",1,381,0,0],["v","Моя душа горит желаньем слышать",0,382,0,0],["v","Твой голос, но боюсь, что тяжело",0,383,0,0],["v","Припоминать тебе…",0,384,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","О нет, не бойся,",1,384,0,0],["v","С тобой твое желание люблю:",0,385,0,0],["v","Все спрашивай, родимая, — отвечу.",0,386,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Скажи, дитя, отчизну потерять",0,387,0,0],["v","Большое зло для человека, точно?",0,388,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Огромное: словами не обнять…",0,389,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Но чем же, чем изгнанник тяготится?",0,390,0,1],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Речей, о мать, свободных он лишен.<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,390,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Удел рабов — трусливо прятать мысли.",0,391,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","А каково от грубости терпеть?",0,392,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Да, жить среди глупцов… какая пытка…",0,393,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Меж тем рабом изгнанник должен быть.",0,394,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Но ведь его надежды окрыляют, —",0,395,0,0],["v","Так говорят…",0,396,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Обманчивые, да.",1,396,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","И в их тщете разуверяет время?",0,397,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","О, сладость слез изгнаннику, поверь,",0,398,0,0],["v","Единое желанье и отрада.",0,399,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Но про себя скажи мне: где же ты",0,400,0,1],["v","До свадьбы жил и чем питался, горький?",0,401,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","День сыт, порой — до завтра потерпи.",0,402,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Отцовские друзья не помогали?",0,403,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","У бедняка ты друга не найдешь…",0,404,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Но кровь тебя от черни отличала…",0,405,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Что в знатности? Ведь ей не проживешь.",0,406,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Итак, всего дороже нам отчизна?",0,407,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Страданьем я пять этих слов купил…",0,408,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Как в Аргос ты попал, с какою целью?",0,409,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Не знаю сам: так, видно, бог велел.",0,413,0,1],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","О мудрый бог! Но как же ты женился?",0,411,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Оракул был от Локсия царю.<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,409,0,1],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Я не пойму… Какой еще оракул?",0,410,0,1],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Адрасту бог дельфийский предвещал,",0,411,0,0],["v","Что дочерей отдаст он льву с кабаном…",0,412,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Что ж общего имеешь ты с зверьми?",0,413,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Уж ночь была, когда к порогу дома",0,415,0,1],["v","Адрастова пришел я.",0,415,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Ты искал",1,415,0,0],["v","Ночлега, как изгнанник бесприютный?",0,416,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Вот именно. За мной пришел другой.",0,417,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Кто ж это был? Как ты, скиталец?.. бедный!",0,418,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Тидей, а сын Ойнеев, говорят.",0,419,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Но почему ж Адраст вообразил,",0,420,0,1],["v","Что звери вы?",0,421,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Из-за циновки жалкой",1,421,0,0],["v","Тягались мы: в борьбе он нас застал.",0,422,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","И… объяснив оракул Аполлона…",0,423,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Он отдал нам двух юных дочерей.",0,424,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Что ж, ты женой доволен иль не очень?",0,425,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Раскаяться покуда не успел…",0,426,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Но войско как склонить ты мог к походу?",0,427,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Адраст зятьям обоим обещал",0,428,0,0],["v","В отечество вернуть их, начиная",0,429,0,0],["v","С меня, — и вот данайцев лучший цвет,",0,430,0,1],["v","Сильнейшие аргосцы здесь со мною;",0,430,0,0],["v","Да, грустная услуга… но она",0,431,0,0],["v","Была необходима… боги знают,",0,432,0,0],["v","Что не своей я волею иду",0,432,0,0],["v","На тех, кто мне всего дороже в мире.",0,433,0,0],["v","Тебе одной, родимая, теперь",0,434,0,0],["v","Нас помирить возможно, — этой распре",0,435,0,0],["v","Одна предел ты можешь положить.",0,435,0,0],["v","О мать моя, склоняя <span class=\"ch\" data-ch=\"eteokl\">Этеокла</span>,",0,436,0,0],["v","Себя и всех фиванцев пожалей",0,437,0,0],["v","И сжалься над своим бездомным сыном…",0,437,0,0],["v","Я истиной избитой заключу",0,438,0,0],["v","Мои слова: на свете только деньги",0,439,0,0],["v","Дают нам власть, вся сила только в деньгах;",0,440,0,1],["v","И если я привел сюда войска,",0,440,0,0],["v","Так оттого, что беден я, а знатный",0,441,0,0],["v","И нищий муж среди людей — ничто.",0,442,0,0],["sp","Корифей"],["v","Сюда идет для совещаний с братом",0,442,0,0],["v","Фиванский царь — уладить их дела,",0,443,0,0],["v","Как матери, тебе, Иокаста, должно.",0,444,0,0],["scene","Явление пятое","s6",2,6],["v","Те же и <span class=\"ch\" data-ch=\"eteokl\">Этеокл</span> в вооружении и со свитой.",0,445,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Мать, ты звала меня — я не хотел",0,445,0,0],["v","Тебя ослушаться, — но, если можно,",0,446,0,0],["v","Приказывай скорее, — я спешу:",0,447,0,0],["v","Там, у ворот, свои войска повзводно<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,447,0,0],["v","Располагать я начал… Столько дел…",0,448,0,0],["v","А тут ко мне явились с приглашеньем…",0,449,0,0],["v","Итак, ты нас задумала мирить",0,450,0,1],["v","И лишь затем меня уговорила",0,450,0,0],["v","Впустить в ограду наших славных стен",0,451,0,0],["v","Вот этого… изменника… Не так ли?",0,451,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["dir","<span class=\"ch\" data-ch=\"eteokl\">Этеоклу</span>"],["v","Поудержись! Поспешность не порука",0,452,0,0],["v","За истину, и плавный ход речей",0,453,0,0],["v","Из мудрых уст нам кажется прекрасней…",0,453,0,0],["v","Свирепый взор и гневное дыханье",0,454,1,0],["v","Смягчи, мой сын. Ты видишь возле нас",0,455,0,0],["v","Не голову Горгоны, на которой",0,455,0,0],["v","Еще свежа пурпуровая кровь…",0,456,0,0],["sd","(Строго.)"],["v","Перед тобой твой брат и гость… Ты слышишь?",0,456,0,0],["sd","(К <span class=\"ch\" data-ch=\"polinik\">Полинику</span>, который стоит спустя голову, между тем как <span class=\"ch\" data-ch=\"eteokl\">Этеокл</span> отвернулся в сторону.)"],["v","Ты ж, Полиник, лица от нас не прячь:",0,457,0,0],["v","Лучами глаз ответных взоров брата",0,458,0,0],["v","Ищи, мой сын: так легче говорить",0,458,0,0],["v","И слушать речь.",0,459,0,0],["sd","<span class=\"ch\" data-ch=\"polinik\">Полиник</span> поднимает голову, но старается не смотреть на брата."],["v","От мудрости житейской",1,459,0,0],["v","Вот мой совет вам, дети: если вы",0,460,0,1],["v","Поговорить сошлись, то гнев взаимный",0,460,0,0],["v","Забыть должны; вы, взорами сплетясь,",0,461,0,0],["v","Одно в уме держать старайтесь дело,",0,462,0,0],["v","Что обсудить решили, а обид",0,463,0,0],["v","И прошлых зол не сохраняйте память!",0,464,0,0],["v","Ты, Полиник, дитя мое, сперва",0,465,1,0],["v","Свое скажи! С дружинами данайцев",0,465,0,0],["v","Тебя сюда обида привела.",0,466,0,0],["v","Не так ли, сын мой? Пусть же бог нас судит",0,467,0,0],["v","И правдою от зол освободит.",0,468,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","У истины всегда простые речи,",0,469,1,0],["v","Она бежит прикрас и пестроты,",0,470,0,1],["v","И внешние не нужны ей опоры,",0,471,0,0],["v","А кривды речь недуг в себе таит,",0,472,0,0],["v","И хитрое потребно ей лекарство.",0,473,0,0],["v","Когда, храня наш древний отчий дом,",0,474,1,0],["v","Проклятием <span class=\"ch\" data-ch=\"edip\">Эдипа</span> осужденный,",0,475,0,0],["v","На целый год я брату уступил",0,476,0,0],["v","Фиванский трон для власти безраздельной,",0,477,0,0],["v","А сам ушел в изгнанье, я не думал,",0,478,0,0],["v","Что мне мечом придется отбирать",0,479,0,1],["v","Имения и власть; мое решенье",0,481,0,1],["v","Он так хвалил, он клялся, и богов",0,481,0,0],["v","В свидетели он призывал, что сменит",0,482,0,0],["v","Меня в изгнании, как только минет год.",0,483,0,0],["v","Но клятвы позабыты… Он владеет",0,484,0,0],["v","Моим добром и трона уступать",0,485,0,0],["v","Не думает. Клянусь, что я сейчас,",0,485,0,0],["v","По праву власть отцовскую приявши,",0,486,0,0],["v","С кадмейских стен осаду снять готов,",0,487,0,0],["v","Чтоб через год опять идти в изгнанье, —",0,488,0,0],["v","Но прав своих я попирать не дам,",0,489,0,0],["v","Покуда меч поддерживать их может.",0,490,0,1],["v","В свидетели бессмертных я зову,",0,490,0,0],["v","Что поступал по правде и отчизны",0,491,0,0],["v","Лишен несправедливо и безбожно…",0,492,0,0],["v","Пусть речь моя не блещет остротой,",0,493,0,0],["v","И груб ее язык прямой. Но правда,",0,494,0,0],["v","По-моему, для мудрых и немудрых",0,495,0,0],["v","Одна на свете — и другой не сыщешь.",0,495,0,0],["sp","Корифей"],["v","Я выросла не в эллинской семье,",0,496,0,0],["v","Но речь твоя мне кажется разумной.",0,497,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["dir","обращается к матери"],["v","Когда бы всем казалось на земле",0,498,1,0],["v","Одно и то же мудрым и прекрасным,",0,499,0,0],["v","Раздоры бы не тяготили мира.",0,500,0,1],["v","Увы! Для рода смертных ничего",0,500,0,0],["v","Нет равного на свете, только имя",0,501,0,0],["v","Уподобляет вещи, а не сущность.",0,501,0,0],["v","Перед тобой желаний не таю:",0,502,1,0],["v","На путь светил полунощных, и в бездну",0,503,0,0],["v","Подземную, и к ложу солнца я",0,503,0,0],["v","За скипетром пошел бы, не колеблясь,",0,504,0,0],["v","Когда бы там он спрятан был. Царей",0,505,0,0],["v","Великих власть среди богов бессмертных —",0,505,0,0],["v","Богиня дивная. А я — фиванский царь!",0,506,0,0],["v","О мать моя, и прав своих державных",0,506,0,0],["v","Я не отдам другому, — пусть их вырвет…",0,507,0,0],["v","Быть подданным захочет только трус,",0,508,0,0],["v","Когда царем он может оставаться…",0,508,0,0],["v","И что же нам угрозе уступать?",0,509,0,0],["v","Иль оттого он сделался правее,",0,510,0,1],["v","Что копьями засеял нам поля.",0,511,0,0],["v","Нет, злая честь досталась бы фиванцам,",0,512,0,0],["v","Когда бы бремя скипетра из рук",0,513,0,0],["v","Мне выбил меч микенский, а пришельцу,",0,514,0,0],["v","Коли он мира ищет, не на меч",0,515,0,0],["v","Прилично опираться, а на речи.",0,516,0,0],["v","Иль слов найти на нашем языке",0,517,0,0],["v","Не смыслит он, что говорит железом?..",0,518,0,0],["v","Довольно… В Фивах подданным моим",0,519,0,0],["v","Он оставаться может. Но престола",0,520,0,1],["v","Я не отдам… И к делу… Загорайтесь,",0,520,0,0],["v","Костры и факелы!.. Острее нож точи!..",0,521,0,0],["v","Коней и колесниц побольше в поле!",0,522,0,0],["v","Когда Неправда нам вручает Власть,",0,523,0,0],["v","Они прекрасны обе. Добродетель",0,524,0,0],["v","Во всем другом готов я соблюдать.<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,525,0,0],["sp","Корифей"],["v","Красою слов недобрые поступки",0,526,0,0],["v","Не прикрывай, царевич, ты не прав.",0,527,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["dir","после некоторой паузы, остановив глаза на <span class=\"ch\" data-ch=\"eteokl\">Этеокле</span>"],["v","Дитя мое! Среди недугов старость",0,528,0,0],["v","Стяжала опыт мудрый, и его",0,529,0,0],["v","Не отвергай, мой сын, а вразумляйся.",0,530,0,1],["v","Из демонов ужаснейший теперь",0,530,0,0],["v","Твоей душой владеет — Жажда чести.",0,531,0,0],["v","Оставь богиню эту! Правды нет",0,532,0,0],["v","В ее устах коварных, и всечасно",0,532,0,0],["v","Она отравой сладкой напояет",0,533,0,0],["v","Цветущие семейства, города…",0,534,0,0],["v","Ты одурманен ею и не видишь",0,534,0,0],["v","Другой прекраснее ее богини,",0,535,0,0],["v","Что Равенством зовется на земле.",0,536,0,0],["v","Среди людей она так мирно правит,",0,536,0,0],["v","Друзей она и ратников роднит",0,537,0,0],["v","И с городом связует город вольный.",0,538,0,0],["v","В ней все: и справедливость и закон.",0,538,0,0],["v","Где нет ее — там нищета и роскошь,",0,539,0,0],["v","Там ненависть и слезы, униженье",0,540,0,1],["v","И дерзость там. И меру нам и вес",0,540,0,0],["v","Она дает и числа образует;",0,541,0,0],["v","И спутница печальная ночей,",0,542,0,0],["v","И ярких дней горящее светило",0,543,0,0],["v","Из года в год и очередь и шаг,",0,544,0,0],["v","Богине той покорны, не меняют,",0,545,0,0],["v","И нет меж ними зависти, а ты,",0,546,0,0],["v","Ты, смертный, в дележе обидишь брата?!",0,547,0,0],["v","А правда где ж, о сын мой? Или так",0,548,0,0],["v","Слепит тебя сияние престола,",0,549,0,0],["v","Что власть царей величием ты мнишь,",0,550,0,1],["v","Прощая ей надменные обиды?",0,550,0,0],["v","О суетность! Тебя манит, дитя,",0,551,0,0],["v","Источник благ, и ты не хочешь видеть",0,552,0,0],["v","На дне его мучительных забот…",0,553,0,0],["v","И что оно, богатство? Тень, названье…",0,554,0,0],["v","Да разве мудрый хочет быть богат?",0,555,0,0],["v","Мы даже не владельцы наших денег,",0,555,0,0],["v","Богам они принадлежат, богам:",0,556,0,0],["v","Хотят — дадут, хотят — опять отнимут…",0,557,0,0],["v","Одумайся ж, перед тобой престол",0,558,1,0],["v","И родина: неужто ж предпочтешь ты",0,559,0,0],["v","Власть царскую спасению своих?..",0,560,0,1],["v","А если брат в бою тебя осилит,",0,560,0,0],["v","И дротики аргосцев отобьют",0,561,0,0],["v","Удар копья фиванского! Подумай:",0,562,0,0],["v","Тебе смотреть придется на разгром",0,563,0,0],["v","Священных Фив, смотреть на пленниц наших",0,563,0,0],["v","Поруганных… и, золото твое,",0,564,0,0],["v","Мечту твою омыв слезами, город",0,565,0,0],["v","Так воззовет с проклятием к тебе:",0,566,0,0],["v","О Этеокл, о злая жажда чести!",0,566,0,0],["sd","(К <span class=\"ch\" data-ch=\"polinik\">Полинику</span>.)"],["v","И ты теперь послушай, <span class=\"ch\" data-ch=\"polinik\">Полиник</span>:<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,567,0,0],["v","Аргосский царь услугою невежды",0,568,0,0],["v","Тебя сманил, и, как ребенок глупый,",0,569,0,0],["v","Ты Фивы жечь с данайцами пришел…",0,570,0,1],["v","Ну хорошо, ты отвоюешь землю, —",0,570,0,0],["v","От слова ведь не станется. А там?",0,571,0,0],["v","Какой трофей воздвигнешь ты Крониду",0,572,0,0],["v","Среди полей отчизны! Да, на нем",0,573,0,0],["v","Прочтут слова: \"Щиты из Фив сожженных",0,573,0,0],["v","Богам приносит <span class=\"ch\" data-ch=\"polinik\">Полиник</span> фиванский\".",0,574,0,0],["v","Не дай-то бог тебе, мой бедный сын,",0,575,0,0],["v","У эллинов добыть такую славу…",0,576,0,0],["v","А если ты здесь будешь побежден,",0,576,0,0],["v","С каким лицом покажешься ты в Аргос?",0,577,0,0],["v","Что скажешь там про горы мертвых тел,",0,578,0,0],["v","Аргосских тел, оставленных в Кадмее?",0,579,0,0],["v","Из скольких уст укоры прозвучат:",0,580,0,1],["v","\"О, жалкий брак! Из-за тебя, Адраст,",0,580,0,0],["v","Из-за твоей затеи мы погибли!\"",0,581,0,0],["v","О Полиник, ты молод и горяч,",0,582,0,0],["v","И две себе теперь ты ямы роешь:",0,582,0,0],["v","Вооружишь ты Аргос на себя",0,583,0,0],["v","Иль здесь среди стяжания погибнешь…",0,584,0,0],["v","А я опять вам, дети, повторю:",0,585,0,0],["v","Заносчивость безумную оставьте, —",0,585,0,0],["v","Ваш дикий спор — для Фив большое зло.",0,586,0,0],["sp","Корифей"],["v","Спасите ж нас, бессмертные, от зол,",0,587,0,0],["v","Иль сыновей <span class=\"ch\" data-ch=\"edip\">Эдипа</span> помирите!",0,587,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Спор окончен; мне сдается — мы напрасно время тратим,",0,588,0,0],["v","И напрасно жар душевный, мать моя, ты расточаешь.",0,589,0,0],["v","Мы иначе не сойдемся, как на прежних основаньях,",0,590,0,1],["v","То есть если он захочет уступить мне власть без споров…",0,591,0,0],["sd","(К матери с полупоклоном.)"],["v","Полагаю, что внушений больше слушать не придется…",0,592,0,0],["sd","(<span class=\"ch\" data-ch=\"polinik\">Полинику</span>.)"],["v","Ты ж немедля нас оставишь, или будешь ты зарезан…",0,593,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Я желал бы видеть панцирь, чтоб удар он вынес этот",0,594,0,0],["sd","(Поднимает меч.)"],["v","И от смерти спасся воин, на меня поднявший руку.",0,595,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Можешь видеть — это близко. Видишь меч, а вот и панцирь.",0,596,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Я спокоен… Жалкой жизнью трус богатый не рискует…",0,597,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","И на труса ты приводишь эти полчища, несчастный!",0,598,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Не безумная отвага — разум нужен полководцу.",0,599,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","О хвастун… Тебе раздолье: крепки клятвы договора.",0,600,0,1],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Слушай, ты, — я повторяю: трон и часть полей отцовских!",0,600,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Это лишнее… Я дома своего не уступаю.",0,601,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Ты моей владеешь частью.",0,602,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Уходи, я говорю!",1,602,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Алтари богов отцовских…",0,603,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Ты, — не я их разорю!",1,603,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Я ограблен.",0,603,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Ты изменник, друг аргосскому царю…",0,604,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Стены братьев белоконных…",0,605,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","О, тебя стыдятся стены.",1,605,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Я был изгнан из отчизны.",0,606,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","И отправился в Микены.",1,606,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Боги! Боги!",0,606,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Ты б не здешних, а аргосских призывал.",0,607,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Нечестивец!",0,608,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Но отчизны я врагам не продавал.",0,609,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Ты грабитель, ты обидчик!",0,610,0,1],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","И убийцей буду скоро.",1,610,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","О отец мой, эти муки…",0,611,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Муки вора, муки вора…",1,611,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Мать моя!..",0,612,0,1],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Ты имя это не достоин повторять.",0,613,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Сестры милые!",0,617,0,1],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Которых ты явился разорять.",0,615,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Фивы!",0,613,0,1],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","В Аргос отправляйся, там взывай к потоку Лерны…",0,613,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["dir","матери, с движением"],["v","О, прости, прости, родная!<a class=\"nr\" href=\"#n-k35\" data-n=\"k35\" aria-label=\"Примечание 35\">35</a>",0,614,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["dir","матери, гневно"],["v","Прочь от скверны, прочь от скверны!",1,614,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Дай с отцом хоть попрощаться.",0,615,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Не прощаяся уйдешь.",1,615,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Дай сестер обнять…",0,616,0,1],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","С Адрастом разве к ним ты попадешь…",1,616,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Мать, прости и будь здорова!",0,618,0,1],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Где уж там: душа томится.",1,618,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Я не сын твой больше, мама.",0,619,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Лучше б мне и не родиться!",1,619,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["dir","указывая на <span class=\"ch\" data-ch=\"eteokl\">Этеокла</span>"],["v","Надо мной он надругался…",0,620,0,1],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Надо ж было расплатиться.",1,620,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["dir","<span class=\"ch\" data-ch=\"eteokl\">Этеоклу</span>"],["v","Где стоять ты будешь в поле?",0,620,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Где стоять?.. А цель твоя?",1,620,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Ополчась, тебя убью я.",0,621,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Не задумаюсь и я…",1,621,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Горе мне!",0,622,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Решенье близко: мы стоим перед судом…",0,623,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Вы Эриний не избегли.",0,623,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Сгибни ж ты, <span class=\"ch\" data-ch=\"edip\">Эдипов</span> дом!",1,623,0,0],["v","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span> в ужасе бежит.",0,624,0,0],["scene","Явление шестое","s7",2,7],["v","Те же, без <span class=\"ch\" data-ch=\"iokasta\">Иокасты</span>.",0,625,0,0],["sp","<span class=\"ch\" data-ch=\"polinik\">Полиник</span>"],["v","Скоро, скоро меч мой праздный жаркой кровью обольется!",0,626,0,0],["v","Будь свидетелем, отчизна, вы, бессмертные, смотрите:",0,626,0,0],["v","Ухожу я обесчещен, от своих оторван силой,",0,627,0,0],["v","Будто я не сын <span class=\"ch\" data-ch=\"edip\">Эдипа</span>, а последний раб фиванский.",0,628,0,0],["v","Если что случится, Фивы, <span class=\"ch\" data-ch=\"polinik\">Полиника</span> не вините:",0,629,0,0],["v","Не своей пришел я волей, изгнан был я из отчизны.",0,630,0,1],["v","Ты же, бог — хранитель улиц, и чертог мой, я с тоскою",0,630,0,0],["v","Покидаю вас, простите! О златые истуканы,",0,631,0,0],["v","Пред которыми так часто кровь овечью возливал я,",0,632,0,0],["v","Вас увижу ль, я не знаю, но не спит надежда в сердце,",0,633,0,0],["v","Что, с разбойником покончив, я царем воссяду в Фивах.",0,634,0,0],["sd","(Уходит.)"],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["dir","вслед ему"],["v","Вон отсюда! О, недаром был ты назван <span class=\"ch\" data-ch=\"polinik\">Полиником</span>,<a class=\"nr\" href=\"#n-k36\" data-n=\"k36\" aria-label=\"Примечание 36\">36</a>",0,635,0,0],["v","И зачинщика раздоров твой отец в тебе провидел.",0,636,0,0],["sd","(Уходит.)"],["scene","Первый музыкальный антракт","s8",2,8],["sp","Хор"],["str","Строфа I"],["v","О, как это было давно!<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,637,2,0],["v","Кадма тирийского",0,638,4,0],["v","В эти поля Аонийские долго телица вела,<a class=\"nr\" href=\"#n-k37\" data-n=\"k37\" aria-label=\"Примечание 37\">37</a>",0,639,0,0],["v","Ига не зная,",0,640,4,1],["v","Долго блуждала…",0,640,4,0],["v","Но там, где городу стать",0,641,2,0],["v","Судили вещания бога,",0,642,2,0],["v","Вдруг ослабев,",0,643,4,0],["v","Четыре колена склонила она и пала на землю.",0,644,0,0],["v","О свежая зелень лугов!",0,645,2,0],["v","О светлое лоно Диркеи",0,645,2,0],["v","И вы, о глубокие нивы!",0,646,2,0],["v","Здесь, здесь нам на радость",0,647,4,0],["v","Гремучего бога",0,648,4,0],["v","Семела явила,",0,649,4,0],["v","И только явила, как плюща",0,650,2,1],["v","Зеленые кудри<a class=\"nr\" href=\"#n-k38\" data-n=\"k38\" aria-label=\"Примечание 38\">38</a>",0,650,4,0],["v","Зевесово чадо, венчая и ластясь, увили.",0,651,0,0],["v","С этого дня поднесь,",0,652,2,0],["v","Плющом украсившись,",0,653,2,0],["v","Жены и девы здесь",0,654,2,0],["v","Эвия славят вакхической пляской, ликуя,",0,655,0,0],["v","Чадо Кронидово.",0,655,2,0],["str","Антистрофа I"],["v","Дракона с кровавым гребнем,",0,656,2,0],["v","С взором сверкающим,",0,657,4,0],["v","Стража потока диркейского, камнем тириец убил",0,658,0,0],["v","У водопоя",0,659,4,0],["v","В кисти могучей…",0,660,4,1],["v","И, вняв Паллады словам,",0,661,2,0],["v","Богини, чудесно рожденной,",0,662,2,0],["v","Зубы его",0,663,4,0],["v","На ниве глубокой и тучной посеял славный тириец.",0,664,0,0],["v","И, лоно земли растерзав,",0,670,2,1],["v","Булатом звеня и сверкая,",0,670,2,0],["v","Чудовища вышли оттуда,",0,671,2,0],["v","Как призрак ужасный,",0,671,4,0],["v","Но только что вышли,",0,672,4,0],["v","Как, яростью полных,",0,672,4,0],["v","Тяжелым ударом железо",0,673,2,0],["v","Гигантов могущих,",0,673,4,0],["v","В губительной распре погибших, Земле воротило.",0,674,0,0],["v","Пала сыновняя",0,675,4,0],["v","Жаркой струею кровь",0,675,4,0],["v","В землю-кормилицу,",0,676,4,0],["v","Что так недавно, дыханьем эфира согрета,",0,676,0,0],["v","Здесь породила их.",0,677,4,0],["str","Строфа II"],["v","Я, молясь, призываю тебя,",0,677,0,0],["v","Праматери Ио",0,678,2,0],["v","Великий потомок,",0,678,2,0],["v","Рождение Зевса.",0,679,2,0],["v","На варварский голос наш",0,680,0,1],["v","Сойди к нам, Эпаф, сойди!",0,680,0,0],["v","К земле обездоленной,",0,681,2,0],["v","К созданию Кадмову,",0,682,2,0],["v","К созданью сынов твоих!",0,682,2,0],["str","Антистрофа II"],["v","Ты почти соименных богинь:<a class=\"nr\" href=\"#n-k39\" data-n=\"k39\" aria-label=\"Примечание 39\">39</a>",0,683,0,0],["v","Одну Персефону,",0,684,2,0],["v","Другую Деметру,",0,685,2,0],["v","Царицу вселенной,",0,685,2,0],["v","Всем тварям кормилицу,",0,686,0,0],["v","Богинь нам пошли, Эпаф!",0,687,0,0],["v","Пусть факел спасения",0,687,2,0],["v","Кадмейцам несут они:",0,688,2,0],["v","Всевластны бессмертные.",0,689,2,0],["act","Действие второе","a3","II"],["scene","Явление седьмое","s9",3,9],["sd","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span> в царской одежде, но без полного вооружения, как дома. За ним стража."],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["dir","солдату"],["v","Ступай, сыщи нам сына <span class=\"ch\" data-ch=\"menekey\">Менекея</span>,<a class=\"nr\" href=\"#n-k40\" data-n=\"k40\" aria-label=\"Примечание 40\">40</a>",0,690,0,1],["v","А матери моей, Иокасты, брата.",0,690,0,0],["v","Скажи ему, что важные дела",0,691,0,0],["v","Фиванские и нашего семейства",0,692,0,0],["v","Немедля с ним я должен обсудить,",0,693,0,0],["v","Пока мы бой еще отсрочить властны.",0,694,0,0],["sd","(Видя приближающегося <span class=\"ch\" data-ch=\"kreont\">Креонта</span>.)"],["v","Ба… вот и он: ногам твоим, солдат,",0,695,0,0],["v","Вельможный князь работы не доставил.",0,695,0,0],["scene","Явление восьмое","s10",3,10],["v","Те же и <span class=\"ch\" data-ch=\"kreont\">Креонт</span>.",0,696,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Насилу-то тебя я разыскал,",0,697,0,0],["v","Царь <span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>, пришлося караулы",0,698,0,0],["v","Мне обойти у всех семи ворот.",0,699,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","И я, Креонт, хотел тебя увидеть:",0,700,0,1],["v","Сегодня был в Кадмее <span class=\"ch\" data-ch=\"polinik\">Полиник</span>, —",0,700,0,0],["v","Согласие меж нами невозможно.",0,701,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Да, я слыхал, что он не в меру горд",0,702,0,0],["v","Своим родством с аргосцем и на силы",0,703,0,0],["v","Надеется, — но это предоставим",0,704,0,0],["v","Богам решать. К тебе, фиванский царь,",0,705,0,0],["v","Я шел теперь за настоящим делом.",0,706,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Что хочешь ты сказать, я не пойму.",0,707,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Есть пленники аргосские у нас.",0,708,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","И новости из лагеря, не так ли?",0,709,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Мы штурма ждать должны со всех сторон…",0,710,0,1],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Скорей же в поле всех вооруженных!",0,711,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Остановись… дитя или слепец!..",0,712,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Туда, за ров, и в бой без промедлений!",0,713,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Да много ль нас, а их — и счета нет…",0,714,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Я знаю их: вся храбрость их до боя.",0,715,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Аргосцев чтит Эллада, <span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>.",0,716,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","А я поля залью аргосской кровью.",0,717,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Дай бог тебе! Но трудно, трудно, царь.",0,718,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","А за стеной оставить можно войско?",0,720,0,1],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Предусмотреть — и значит победить:",0,721,0,0],["v","Вот что тебе советую припомнить.",0,722,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Других путей поищем, если так.",0,723,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Придумывай, пока еще не поздно.",0,724,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Что, если ночью вылазку устроить?",0,725,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Во тьме ночей несчастия таятся.",0,727,0,1],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","И им и нам, но смелых бог хранит.",0,726,0,1],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Да, хорошо, как спрятаться успеешь…",0,725,0,1],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Успеешь ли… Диркея глубока.",0,730,0,1],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Придумано не дурно, но защита",0,730,0,0],["v","Надежная, по-моему, верней.",0,729,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","И все-таки в обед я нападаю.",0,728,0,1],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Пугнуть — пугнешь, а надо победить.",0,729,0,1],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","А конница? Набег кавалерийский?",0,732,0,1],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Колесами их лагерь обнесен.<a class=\"nr\" href=\"#n-k41\" data-n=\"k41\" aria-label=\"Примечание 41\">41</a>",0,733,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Но где же выход, неужели сдаться?",0,734,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Зачем? С умом всегда найдешь исход.",0,735,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Коли умен, придумай. Мы ж посудим.",0,736,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Там семь вождей в их стане — я слыхал.",0,737,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Как, семь вождей? Командовать над горстью?",0,738,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["dir","подсказывая ему"],["v","И наших войск движения следят.<a class=\"nr\" href=\"#n-k42\" data-n=\"k42\" aria-label=\"Примечание 42\">42</a>",0,739,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Постой, Креонт, необходимы меры,",0,740,0,1],["v","И быстрые, — не за горою враг…",0,740,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["dir","быстро"],["v","Царь, семь вождей пошли к семи воротам!",0,741,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Начальствовать иль предлагаешь ты",0,742,0,0],["v","Устроить ряд кровавых поединков?",0,743,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Начальствовать, и лучших избери.",0,744,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Чтоб удалить возможность штурма башен?",0,745,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["dir","продолжает"],["v","Помощников надежных им поставь…",0,745,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["dir","насмешливо"],["v","Что ж, посмелей иль только осторожных?",0,746,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Без смелости чего же стоит ум",0,747,0,0],["v","И глупая кому потребна смелость?",0,748,0,0],["sp","<span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>"],["v","Пусть будет так. Лохагов назначать,",0,749,1,0],["v","Аргосскому последуя примеру,",0,750,1,1],["v","Сейчас иду я в город семивратный…",0,751,1,0],["v","Перечислять намеченных теперь",0,752,1,0],["v","Не время, кажется, когда враги так близко.",0,753,1,0],["v","Но для себя я место приберег:",0,754,1,0],["v","Я стану там, где встречу <span class=\"ch\" data-ch=\"polinik\">Полиника</span>.",0,755,1,0],["v","И если я не ворочусь, Креонт,",0,756,1,0],["v","Не позабудь устроить брак Гемона:",0,757,1,0],["v","С сестрой моей его я сговорил,<a class=\"nr\" href=\"#n-k43\" data-n=\"k43\" aria-label=\"Примечание 43\">43</a>",0,758,1,0],["v","Так обрученья повторять не надо…",0,760,1,1],["v","Тебе, Креонт, я оставляю дом;",0,760,1,0],["v","Ты — дядя мне и кровных не обидишь.",0,761,1,0],["v","<span class=\"ch\" data-ch=\"iokasta\">Иокасту</span>-мать в довольстве содержи, —",0,762,1,0],["v","Кто ближе нам: тебе и мне, вельможный?",0,763,1,0],["v","Старик отец в безумии своем",0,763,1,0],["v","Сам осудил себя на ослепленье:",0,764,1,0],["v","За яростный поток его проклятий",0,765,1,0],["v","На голову детей его хвалить",0,766,1,0],["v","Я не могу, конечно, и сегодня ж",0,766,1,0],["v","Они меня раздавят, может быть.",0,767,1,0],["v","Все, кажется?.. Да разве вот еще, —",0,768,1,0],["v","Тиресия-гадателя мы спросим.",0,769,1,0],["v","К нему пошлю я сына твоего,",0,770,1,1],["v","Что имя деда носит, <span class=\"ch\" data-ch=\"menekey\">Менекея</span>.",0,770,1,0],["v","И пусть тебе советы старец вещий",0,771,1,0],["v","Свои подаст: меня он невзлюбил,",0,772,1,0],["v","С тех пор как раз при нем на их искусство",0,772,1,0],["v","Я нападал.",0,773,1,0],["v","Последний мой приказ<a class=\"nr\" href=\"#n-k44\" data-n=\"k44\" aria-label=\"Примечание 44\">44</a>",1,773,0,0],["v","Тебе, Креонт, с фиванцами, — коль боги",0,774,1,0],["v","Победу мне сегодня ниспошлют,",0,775,1,0],["v","Пускай никто из граждан <span class=\"ch\" data-ch=\"polinik\">Полиника</span>",0,775,1,0],["v","В земле родной не смеет хоронить,",0,776,1,0],["v","И кто бы ни ослушался, казните!",0,777,1,0],["sd","(Страже.)"],["v","А вы ступайте живо во дворец!",0,777,1,0],["v","Оружие мне нужно: щит тяжелый,",0,778,1,0],["v","И поножи, и панцирь, и шелом,",0,779,1,0],["v","Копье и меч. Иду я за отчизну",0,780,1,1],["v","На праведный и благородный бой…",0,780,1,0],["v","Ты ж, из богинь богиня, Осторожность,",0,781,1,0],["v","Храни мой дом и Фивы без меня!",0,781,1,0],["sd","(Уходит. За ним <span class=\"ch\" data-ch=\"kreont\">Креонт</span> и стража.)"],["scene","Второй музыкальный антракт","s11",3,11],["sp","Хор"],["str","Строфа"],["v","О печалью богатый Арей,",0,782,0,0],["v","О бог,",0,782,2,0],["v","Обагренный кровью убитых,",0,783,0,0],["v","Диониса веселого чуждый!",0,784,0,0],["v","Для чего не идешь, господин,",0,784,0,0],["v","Туда, где юность ликует,",0,785,0,0],["v","В хороводах сплетаясь светлых,",0,785,0,0],["v","Где, плющом и тисом увитый,",0,786,0,0],["v","Волос золотистых локон",0,787,0,0],["v","У пляшущей девы Хариты",0,787,0,0],["v","И ходит, и вьется, и пляшет",0,788,0,0],["v","Под сладкую музыку флейты?..",0,788,0,0],["v","Зачем тебе любо, суровый,",0,789,1,0],["v","На Фивы по жаркому полю",0,790,0,1],["v","Ряды железных данайцев",0,790,0,0],["v","Под медные звуки двигать?",0,791,0,0],["v","То не Бромий тирсом безумья<a class=\"nr\" href=\"#n-k45\" data-n=\"k45\" aria-label=\"Примечание 45\">45</a>",0,791,1,0],["v","Толпу неподвижную тронул,",0,792,0,0],["v","Что там, на брегах Исмена,",0,793,0,0],["v","И шум и пыль поднялися,",0,793,0,0],["v","Что, в вихре кружась, замелькали",0,794,0,0],["v","Колеса, и люди, и мулы,",0,795,0,0],["v","А конные мчатся рядами —",0,795,0,0],["v","То Арей дыханьем вздымает",0,796,0,0],["v","Фиванцев, отродье спартов,",0,796,0,0],["v","И у каменных стен Амфиона",0,797,0,0],["v","Ополчаются медные люди.",0,798,0,0],["v","То ты, богиня, Вражда,",0,798,1,0],["v","Для горького дома Лабдака",0,799,0,0],["v","Готовишь новые беды.",0,800,0,1],["str","Антистрофа"],["v","О священная лень лесов,",0,800,0,0],["v","И ты,",0,801,2,0],["v","Киферон, венчанный снегами,",0,801,0,0],["v","Артемиды алмаз бесценный!",0,802,0,0],["v","Для чего ты хранил, Киферон,",0,802,0,0],["v","<span class=\"ch\" data-ch=\"iokasta\">Иокасте</span> сына <span class=\"ch\" data-ch=\"edip\">Эдипа</span>,",0,803,0,0],["v","Что когда-то из сени отчей",0,803,0,0],["v","На голые скалы был брошен",0,804,0,0],["v","С пронизанной златом пяткой?<a class=\"nr\" href=\"#n-k46\" data-n=\"k46\" aria-label=\"Примечание 46\">46</a>",0,804,0,0],["v","Зачем, о крылатая дева,<a class=\"nr\" href=\"#n-k47\" data-n=\"k47\" aria-label=\"Примечание 47\">47</a>",0,805,0,0],["v","Из дебрей ты в Фивы летела",0,805,0,0],["v","С загадкой своей печальной?",0,806,0,0],["v","И, лютое горе рождая,",0,806,1,0],["v","Потомков великого Кадма",0,807,0,0],["v","В когтях уносила хищных",0,807,0,0],["v","К сиянью лазури вечной?",0,808,0,0],["v","Знать, тебя, крылатое диво,",0,808,1,0],["v","Из царства поддонного мрака",0,809,0,0],["v","Аид посылал могучий",0,810,0,1],["v","На гибель кадмейскому роду…",0,810,0,0],["v","А ныне тебя заменила",0,811,0,0],["v","Ужасная братская распря…",0,812,0,0],["v","О, горе, о, злое рожденье,",0,812,0,0],["v","Когда мать от сына рождает,",0,813,0,0],["v","О, грех, кровавый и страшный,",0,814,0,0],["v","Когда сын наслажденье вкушает,",0,814,0,0],["v","Попирая матери ложе.",0,815,0,0],["v","От вас, объятья греха,",0,816,1,0],["v","Родиться может ли счастье",0,816,0,0],["v","Иль добрые дети родиться?",0,817,0,0],["str","Эпод"],["v","…В те давние дни",0,818,2,0],["v","Нивы земли фиванской,",0,818,2,0],["v","Зубы прияв дракона,",0,819,2,0],["v","Ярким венчанного гребнем,",0,820,2,1],["v","Племя мужей родили,",0,820,2,0],["v","Первую славу отчизне…<a class=\"nr\" href=\"#n-k48\" data-n=\"k48\" aria-label=\"Примечание 48\">48</a>",0,821,2,0],["v","На брак Гармонии дивной",0,822,2,0],["v","Бессмертные боги стекались,",0,822,2,0],["v","И стены из белого камня",0,823,2,0],["v","Вставали под пение арфы,",0,824,2,0],["v","Под звон Амфионовой лиры",0,824,2,0],["v","Твердыни Кадмеи вставали,",0,825,2,0],["v","В долине, где зелень лугов",0,826,2,0],["v","Исмен волной орошает",0,826,2,0],["v","И близко к нему подбегают",0,827,2,0],["v","Диркеи резвые волны.",0,828,2,0],["v","С оного дня, как праматерь рогатая Ио",0,828,0,0],["v","Первого предка кадмейских царей породила,",0,829,0,0],["v","Сколько вы славных имен,",0,830,2,1],["v","Сколько вы подвигов славных,",0,830,2,0],["v","Фивы родные, узрели!",0,831,2,0],["v","А теперь ваш блеск военный",0,832,2,0],["v","Должен ярко разгореться,",0,832,2,0],["v","Или… вспыхнуть и угаснуть…",0,833,2,0],["act","Действие третье","a4","III"],["scene","Явление девятое","s12",4,12],["sd","<span class=\"ch\" data-ch=\"kreont\">Креонт</span> и Тиресий в золотом венце (идет, нащупывая путь палкой и ступая мелкими шагами старого слепца)"],["sp","Тиресий"],["v","О дочь моя, для старого слепца",0,834,0,0],["v","Ты око и опора, как во мраке",0,834,0,0],["v","Для корабля полнощное светило…",0,835,0,0],["v","Я посохом ощупываю путь…",0,836,0,0],["v","Идти легко… Тут гладкая дорога…",0,836,0,0],["v","Но я устал… Передохнем, дитя…",0,837,0,0],["sd","(Осматривается, тяжело дыша.)"],["v","Смотри же, дочь, храни в руке девичьей",0,838,0,0],["v","Те записи гаданий, где судьба<a class=\"nr\" href=\"#n-k49\" data-n=\"k49\" aria-label=\"Примечание 49\">49</a>",0,838,0,0],["v","Фиванская начертана богами, —",0,839,0,0],["v","В святилище моем я их прочел.",0,840,0,1],["v","А ты, дитя Креонтово, скажи нам,",0,840,0,0],["v","Далеко ли до города? Меня",0,841,0,0],["v","Усталые колени уж не носят",0,842,0,0],["v","И частые измучили шаги…",0,843,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Привет тебе!.. Ладью свою, Тиресий,",0,844,0,0],["v","Останови у дружеских брегов!",0,845,0,0],["sd","(<span class=\"ch\" data-ch=\"menekey\">Менекею</span>.)"],["v","А ты, мой сын, слепому будь поддержкой:",0,845,0,0],["v","Младенческим и старческим ногам",0,846,0,0],["v","Опора рук чужих всегда приятна.",0,847,0,0],["sp","Тиресий"],["dir","не садясь на приглашение <span class=\"ch\" data-ch=\"menekey\">Менекея</span>"],["v","Но ты, Креонт, по делу звал меня,",0,848,0,0],["v","И спешному? Ты ждешь моих советов?",0,849,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["dir","усаживая его"],["v","Успеется… Передохни, старик,",0,850,0,1],["v","И, скинув с плеч томленье путевое,",0,850,0,0],["v","Остатки сил упавших собери!",0,851,0,0],["sp","Тиресий"],["dir","садится"],["v","Да, тяжко мне! Подумать, что вчера,",0,852,0,0],["v","Вчера еще победу Кекропидам",0,853,0,0],["v","В войне с царем фракийским указав,<a class=\"nr\" href=\"#n-k50\" data-n=\"k50\" aria-label=\"Примечание 50\">50</a>",0,854,0,0],["v","Златой венец приял я за вещанья,",0,855,0,0],["v","Добычи их афинской первый дар.",0,856,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Твой золотой венец, о старец вещий,",0,857,0,0],["v","Да явится нам знаменьем благим!",0,858,0,0],["v","Ты видишь нас, Тиресий, в море бедствий:",0,859,0,0],["v","Данайцами теснимые, подъемлем",0,860,0,1],["v","Мы тяжкий бой, и во главе дружин",0,860,0,0],["v","Фиванский царь копье уже поставил…",0,861,0,0],["v","Что делать нам, Тиресий, укажи,",0,862,0,0],["v","Чем городу теснимому поможем?",0,863,0,0],["sp","Тиресий"],["v","Я вещих уст не стал бы размыкать",0,864,4,0],["v","Для вашего царевича, но если",0,865,4,0],["v","Тебе, Креонт, гадания нужны,",0,865,4,0],["v","Я говорить готов.",0,866,4,0],["sd","(Перебирает в руках таблички, взятые у Манто.)"],["v","Ваш город страждет",0,867,4,0],["v","Уже давно, с тех пор как, против воли",0,868,4,0],["v","Богов, <span class=\"ch\" data-ch=\"edip\">Эдип</span> был зачат. И его",0,869,4,0],["v","Незрячие и кровью налитые",0,870,4,1],["v","Глаза теперь для эллинов урок…",0,870,4,0],["v","А сыновья, которые слепого",0,871,4,0],["v","Темницею задумали карать,",0,872,4,0],["v","Как будто мало кары олимпийской,",0,872,4,0],["v","Они — глупцы надменные, и только…",0,873,4,0],["v","Когда, лишив несчастного слепца",0,874,4,0],["v","Его богатств, последнее — свободу —",0,875,4,0],["v","Они отнять дерзнули беззаконно,",0,875,4,0],["v","Разгневанный, он изрыгнул на них",0,876,4,0],["v","Тяжелые отцовские проклятья;",0,877,4,0],["v","Чего тогда не делал я, чего",0,877,4,0],["v","Не говорил я сыновьям <span class=\"ch\" data-ch=\"edip\">Эдипа</span> —",0,878,4,0],["v","Лишь ненависть ответом мне была.",0,879,4,0],["sd","(Встает и, переложив дощечки в левую руку, жестикулирует правой.)"],["v","Теперь, Креонт, внемли вещаньям Феба:",0,880,4,1],["v","Для сыновей <span class=\"ch\" data-ch=\"edip\">Эдипа</span> настает",0,880,4,0],["v","Последний бой, и ми один не встанет…",0,881,4,0],["v","А городу придется пережить",0,881,4,0],["v","Дни тяжких жертв: я вижу, как на трупы",0,882,4,0],["v","Кровавых тел ложится свежий ряд,",0,883,4,0],["v","И стон земли фиванской наполняет",0,883,4,0],["v","Мне ужасом взволнованную душу.",0,884,4,0],["v","О город мой, в обломках погребен,",0,885,4,0],["v","Ты узришь смерть, коль слов моих не примешь.",0,885,4,0],["v","Вот первое: да не царит в тебе",0,886,4,0],["v","И да не будет даже гражданином",0,886,4,0],["v","К Эдипову принадлежащий роду.",0,887,4,0],["v","Безумию подвержен этот род,",0,888,4,0],["v","И Фивы он увлечь в погибель может.",0,888,4,0],["sd","(Помолчав.)"],["v","От ваших мук теперешних одно",0,889,4,0],["v","На свете есть, но горькое лекарство,",0,890,4,1],["v","И я его не буду называть…",0,890,4,0],["v","Гадателю опасно, а владыкам",0,891,4,0],["v","Не радостно отечества алтарь",0,892,4,0],["v","Такою жертвой пенною украсить.",0,893,4,0],["sd","(Берет посох из рук дочери и возвращает ей дощечки.)"],["v","Но я устал… Пора на отдых мне…",0,893,4,0],["v","Грядущее приму я, как другие,",0,894,4,0],["v","А умереть придется — не спасусь…",0,895,4,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Ни с места, ты…",0,896,0,0],["sp","Тиресий"],["v","О, не проси, несчастный!",1,896,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Бежишь?",0,896,0,0],["sp","Тиресий"],["v","Бегу ль? Судьба тебя бежит…",0,897,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Лекарство нам открой, твое лекарство…",0,898,0,0],["sp","Тиресий"],["v","Теперь «открой», а там «молчи, молчи!».",0,899,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Я откажусь спасти мою отчизну?!",0,900,0,1],["sp","Тиресий"],["v","Так точно ты лекарство хочешь знать?",0,901,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Для сердца нет заманчивее тайны…",0,902,0,0],["sp","Тиресий"],["v","Попомни же и слушай, если так.",0,903,0,0],["v","Но нет, сперва скажи, куда девался",0,904,0,0],["v","Меня к тебе приведший <span class=\"ch\" data-ch=\"menekey\">Менекей</span>?",0,905,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Он здесь, старик.",0,906,0,0],["sp","Тиресий"],["v","Пускай же удалится,",1,906,0,0],["v","Он этих слов моих не должен знать.",0,907,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Оставь, мой сын сберечь сумеет тайну.",0,908,0,0],["sp","Тиресий"],["v","Ты требуешь, чтоб я вещал при нем?",0,909,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Зачем лишать его отрадной вести!..",0,910,0,1],["sp","Тиресий"],["v","Внемли ж божественным вещаньям уст моих!",0,910,0,0],["v","Вот этого ребенка, Менекея,",0,911,0,0],["v","Отчизне в дар ты должен заколоть…",0,912,0,0],["v","И сам судьбу на голову накликал!",0,913,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["dir","отступает с легким стоном"],["v","Что говоришь, что говоришь, старик?",0,914,0,0],["sp","Тиресий"],["v","Или слова мои тебе не ясны?",0,915,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","О, тяжек смысл твоих крылатых слов…",0,916,0,0],["sp","Тиресий"],["v","Но крылья их несут спасенье Фивам.",0,917,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Что Фивы мне?! Ты ничего, старик,",0,918,0,0],["v","Не говорил, я ничего не слышал…",0,919,0,0],["sp","Тиресий"],["v","Иль наш <span class=\"ch\" data-ch=\"kreont\">Креонт</span> богами подменен?",0,920,0,1],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["dir","обнимая сына"],["v","Иди, старик. Гаданий нам не надо…",0,920,0,0],["sp","Тиресий"],["v","Иль истины не стало на земле",0,921,0,0],["v","С тех пор, как ты несчастием постигнут?",0,922,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","О, я молю тебя, твоих колен",0,922,0,0],["v","И бороды твоей касаясь белой…",0,923,0,0],["sp","Тиресий"],["v","Зачем молить — ты слышал и терпи!",0,924,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Молю… чтоб ты своих гаданий страшных",0,925,0,0],["v","Кому-нибудь из граждан не открыл…",0,925,0,0],["sp","Тиресий"],["v","Преступного не вымолишь молчанья…",0,926,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Иль ты его своей рукой убьешь?",0,927,0,0],["sp","Тиресий"],["v","Зачем? Скажу… Найдется исполнитель…",0,927,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Но это зло, скажи, откуда ж зло",0,928,0,0],["v","Мне и ему, безвинному, Тиресий?",0,929,0,0],["sp","Тиресий"],["v","Ты прав, отец, желая это знать",0,930,0,1],["v","И объяснений <em>требуя</em>, в пещере,",0,930,0,0],["v","Где жил Дракон, хранитель вод диркейских",0,931,0,0],["v","И сын Земли, он должен быть убит…",0,932,0,0],["v","Там кровь его, на землю пролитая,",0,933,0,0],["v","За Кадмову победу заплатив,",0,933,0,0],["v","С обиженным вас примирит Ареем",0,934,0,0],["v","И Землю-мать отрадой напоит…",0,935,0,0],["v","Да, плод за плод прияв и чистой кровью",0,936,0,0],["v","Месть давнюю насытив, будут к вам",0,936,0,0],["v","Арей и мать Дракона благосклонны, —",0,937,0,0],["v","Та мать, которая из лона золотой",0,938,0,0],["v","Взрастила здесь и дивный колос спартов…",0,939,0,0],["v","О, в жертву им не чуждая должна",0,940,0,1],["v","Пролиться кровь, Драконова, родная,",0,941,0,0],["v","И так как ты единственный потомок",0,942,0,0],["v","Погибших спартов, а Гемон, твой сын,",0,943,0,0],["v","Как обрученный в жертву не годится, —",0,944,0,0],["v","Так умереть твой младший осужден.",0,945,0,0],["v","Он кровию, ребенок непорочный,",0,946,0,0],["v","Родные Фивы может возвеличить",0,947,0,0],["v","И погубить данайцев, ⟨сделав горьким",0,950,0,1],["v","Возврат Адраста в Аргос;⟩ а тебе",0,950,0,0],["v","Два жребия я указал: отчизну",0,951,0,0],["v","Иль сына выбери — обоих не спасешь…<a class=\"nr\" href=\"#n-k51\" data-n=\"k51\" aria-label=\"Примечание 51\">51</a>",0,952,0,0],["v","Свой тяжкий долг исполнил твой отец,",0,953,0,0],["v","О дочь моя! Домой пойдем — судьбою",0,953,0,0],["v","Обижены мы, вещие: коль правду",0,954,0,0],["v","Им говоришь, так от людей укор,",0,955,0,0],["v","А пожалеть нельзя — обидишь бога.",0,956,0,0],["v","Нет, возвещать грядущее один",0,956,0,0],["v","Дельфийский бог свободен. Чужды Фебу",0,957,0,0],["v","И бледный страх, и жалость, и печали.",0,958,0,0],["sd","(Уходит, с ним Манто.)"],["scene","Явление десятое","s13",4,13],["v","<span class=\"ch\" data-ch=\"kreont\">Креонт</span> и <span class=\"ch\" data-ch=\"menekey\">Менекей</span>. Продолжительная пауза.",0,959,0,0],["sp","Корифей"],["v","Молчание уста тебе сковало,",0,960,0,1],["v","О, говори: я так поражена…",0,960,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Чего ж ты ждешь? Еще ль не угадала,",0,961,0,0],["v","Что я скажу? Конечно, нет и нет…",0,962,0,0],["v","Иль должен я из жалости к отчизне",0,963,0,0],["v","Ей сына жертвовать? Да разве боги,",0,963,0,0],["v","Вселяя в нас отцовскую любовь,",0,964,0,0],["v","От смертного потребовать решатся,",0,965,0,0],["v","Чтоб палачам детей он отдавал?..",0,966,0,0],["v","Не надо мне благословений, кровью",0,966,0,0],["v","Сыновнею обрызганных… (Помолчав.) Но сам,",0,967,0,0],["v","Созревший для косы на ниве колос,",0,968,0,0],["v","Я рад сейчас за Фивы умереть…",0,969,0,0],["sd","(<span class=\"ch\" data-ch=\"menekey\">Менекею</span>.)"],["v","Дитя мое, пока спокоен город,",0,970,0,1],["v","Вещания безумные презрев,",0,971,0,0],["v","Беги, покинь фиванские пределы…",0,972,0,0],["v","О, только бы поспеть, пока его",0,973,0,0],["v","Гадания начальникам известны",0,974,0,0],["v","Не сделались и боевым вождям…",0,975,0,0],["v","Не медли, сын, нам дороги мгновенья.",0,976,0,0],["sp","<span class=\"ch\" data-ch=\"menekey\">Менекей</span>"],["v","Бежать? Куда? В чей город и к кому?",0,977,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","О, только дальше, дальше от Кадмеи…",0,978,0,0],["sp","<span class=\"ch\" data-ch=\"menekey\">Менекей</span>"],["v","Но надо знать, отец, куда бежишь…",0,979,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","За Дельфами…",0,980,0,1],["sp","<span class=\"ch\" data-ch=\"menekey\">Менекей</span>"],["v","За Дельфами… а дальше?",1,980,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","В Этолию…",0,980,0,0],["sp","<span class=\"ch\" data-ch=\"menekey\">Менекей</span>"],["v","Положим, а затем?",0,981,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Феспрот слыхал?<a class=\"nr\" href=\"#n-k52\" data-n=\"k52\" aria-label=\"Примечание 52\">52</a>",0,982,0,0],["sp","<span class=\"ch\" data-ch=\"menekey\">Менекей</span>"],["v","Где славный храм додонский?",1,982,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Ну да.",0,983,0,0],["sp","<span class=\"ch\" data-ch=\"menekey\">Менекей</span>"],["v","Но кто ж скитальца приютит?",0,984,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Бог защитит тебя…",0,985,0,0],["sp","<span class=\"ch\" data-ch=\"menekey\">Менекей</span>"],["v","А деньги, деньги?",1,985,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Дам золота тебе я.",0,985,0,0],["sp","<span class=\"ch\" data-ch=\"menekey\">Менекей</span>"],["v","Хорошо…",1,985,0,0],["v","Иди, отец… а мне проститься надо",0,986,0,0],["v","С твоей сестрой родимою, — когда",0,987,0,0],["v","Без матери остался я, <span class=\"ch\" data-ch=\"iokasta\">Иокаста</span><a class=\"nr\" href=\"#n-k53\" data-n=\"k53\" aria-label=\"Примечание 53\">53</a>",0,988,0,0],["v","На грудь к себе сиротку приняла.",0,989,0,0],["v","Я ей скажу: «Прости», — и отправляюсь.",0,990,0,1],["v","<span class=\"ch\" data-ch=\"kreont\">Креонт</span> уходит.",0,990,0,0],["scene","Явление одиннадцатое","s14",4,14],["sp","<span class=\"ch\" data-ch=\"menekey\">Менекей</span>"],["v","О женщины! Согласием притворным",0,991,0,0],["v","Утишил я тревожный дух отца,",0,992,0,0],["v","И долее таиться мне не надо…",0,992,0,0],["v","\"Уйди, — он говорил, — и город брось",0,993,0,0],["v","На произвол судьбы!\" Такую трусость",0,994,0,0],["v","Простят, конечно, люди старику.",0,994,0,0],["v","Отцу простят — но сына, что отчизну",0,995,0,0],["v","Мог выручить и предал, проклянут:",0,996,0,0],["v","Изменникам отчизна не прощает.",0,996,0,0],["v","Довольно… Жизнь я отдаю богам…",0,997,0,0],["v","Какой позор! Когда у стен фиванских",0,998,0,0],["v","Сограждане, отчизну заступив,",0,998,0,0],["v","Свои щиты поставили бесстрашно,",0,999,0,0],["v","И хоть на смерть их Феб не осуждал,",0,1000,0,1],["v","Ареевых не избегают взоров, —",0,1000,0,0],["v","Тот человек, который может смертью",0,1001,0,0],["v","От тяжких мук отчизну исцелить,",0,1002,0,0],["v","Становится предателем отцовским,",0,1003,0,0],["v","И братним, и фиванским… Нет и нет!",0,1004,0,0],["v","Да и куда пошел бы я?.. Для труса",0,1005,0,0],["v","Почет один в отчизне и в бегах…",0,1005,0,0],["v","А ты, Арей, кровавый житель неба,",0,1006,0,0],["v","Когда-то здесь воздвигший из земли",0,1007,0,0],["v","Чудовищных владык земли фиванской,",0,1008,0,0],["v","Внемли мне, бог! На башню я иду",0,1009,0,0],["v","Себя казнить, и в черную обитель",0,1010,0,1],["v","Драконову моя прольется кровь,",0,1011,0,0],["v","Как повелел <span class=\"ch\" data-ch=\"kreont\">Креонту</span> старец вещий.",0,1012,0,0],["v","Не бедный дар тебе я приношу,",0,1013,1,0],["v","Фиванский край, недуг твой исцеляя…",0,1014,0,0],["v","И если бы стране своей служить",0,1015,0,0],["v","Желали все, себя забыв, — для мира",0,1016,0,0],["v","Настали бы златые времена.",0,1017,0,0],["sd","(Уходит.)"],["scene","Третий музыкальный антракт","s15",4,15],["sp","Хор"],["str","Строфа"],["v","Зачем, скажи, крылатая,",0,1018,0,0],["v","Ехидны порождение,",0,1020,0,1],["v","Исчадье мрака адского,",0,1020,0,0],["v","До половины девушка,",0,1021,0,0],["v","До половины чудище,",0,1022,0,0],["v","Зачем ты прилетала к нам?",0,1023,0,0],["v","О крылья беспокойные,",0,1024,0,0],["v","О когти кровожадные,",0,1025,0,0],["v","Зачем брега диркейские",0,1025,0,0],["v","Опустошали вы?",0,1026,0,0],["v","И юношей, измученных",0,1027,0,0],["v","Загадкой невеселою,",0,1028,0,0],["v","Зачем в лазурь умчали вы?",0,1029,0,0],["v","Беды несносные,",0,1030,2,1],["v","Нам ты судил, Арей,",0,1031,2,0],["v","Матери плакали,",0,1032,2,0],["v","Девушки плакали,",0,1033,2,0],["v","Жалобой улицы,",0,1034,2,0],["v","Стоном дома полны",0,1035,2,0],["v","Были фиванские.",0,1036,2,0],["v","И смешанный гул причитаний,",0,1037,0,0],["v","Как гром, рассекало стенанье,",0,1040,0,1],["v","Когда уносила колдунья",0,1041,0,0],["v","Из города новую жертву.<a class=\"nr\" href=\"#n-k54\" data-n=\"k54\" aria-label=\"Примечание 54\">54</a>",0,1042,0,0],["str","Антистрофа"],["v","Но вот <span class=\"ch\" data-ch=\"edip\">Эдип</span>, подвигнутый",0,1043,0,0],["v","Дельфийского оракула",0,1044,0,0],["v","Словами злополучными,",0,1045,0,0],["v","Принес им радость краткую",0,1046,0,0],["v","И новые страдания…",0,1047,0,0],["v","Победою украшенный,",0,1048,0,0],["v","На матери женился сын,",0,1049,0,0],["v","И после, кровью залитый,",0,1050,0,1],["v","Проклятьями на смертный бой",0,1050,0,0],["v","Он <em>сыновей</em> привел…",0,1051,0,0],["v","Хвала тебе, хвала тебе,",0,1052,0,0],["v","За родину любимую",0,1053,0,0],["v","Себя обрекший гибели!",0,1054,0,0],["v","Стоны оставил ты",0,1055,2,0],["v","Старцу-родителю,",0,1056,2,0],["v","Граду ж фиванскому,",0,1057,2,0],["v","Семиворотному,",0,1058,2,0],["v","Славу оставишь ты…",0,1059,2,0],["v","Счастливы матери,",0,1060,2,1],["v","Если таких родят.",0,1060,2,0],["v","О, если б их жребий счастливый",0,1061,0,0],["v","Дала нам Паллада, что камень,",0,1062,0,0],["v","Начало всех бедствий фиванских,",0,1062,0,0],["v","Вручила убийце Дракона…",0,1063,0,0],["act","Действие четвертое","a5","IV"],["scene","Явление двенадцатое","s16",5,16],["v","Вестник-оруженосец.",0,1064,4,0],["v","Продолжительный и нетерпеливый стук в дверь.",0,1065,0,0],["sp","Вестник"],["v","Эй!.. Эй… Да есть ли кто там? Отоприте…",0,1065,0,0],["v","К царице я… Царицу поскорей",0,1066,0,0],["v","Мне надо видеть, люди, <span class=\"ch\" data-ch=\"iokasta\">Иокасту</span>.",0,1067,0,0],["v","Ворота отворяются, и вдали видна идущая <span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>.",0,1067,0,0],["scene","Явление тринадцатое","s17",5,17],["v","Вестник и <span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>.",0,1068,0,0],["v","Ты жалобы и слезы позабудь,",0,1069,0,0],["v","Эдипова преславная супруга,",0,1070,0,1],["v","И ухо приклони к моим речам.",0,1071,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["dir","тревожно"],["v","О милый мой! Иль новое несчастье?..",0,1072,0,0],["v","Царь <span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>, с которым ты ушел,",0,1073,0,0],["v","Мой сын, мой сын, скажи скорее, вестник:",0,1074,0,0],["v","Он жив еще?",0,1075,0,0],["sp","Вестник"],["v","Да, жив он, госпожа.",1,1075,0,0],["v","Жив и здоров, о нем не беспокойся…",0,1076,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","А стены что? Как башни на стенах?",0,1077,0,0],["sp","Вестник"],["v","Целехоньки, и город наш не тронут…",0,1078,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Но враг грозил, не правда ли, стенам?",0,1080,0,1],["sp","Вестник"],["v","Да, дело там лихое завязалось,",0,1080,0,0],["v","Но наш Арей кадмейский устоял",0,1081,0,0],["v","Против копья микенского, царица…",0,1082,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Скажи еще одно, ради богов:",0,1083,0,0],["v","Мой <span class=\"ch\" data-ch=\"polinik\">Полиник</span>, он жив, он видит солнце?",0,1084,0,0],["sp","Вестник"],["v","Да живы оба сына, госпожа…",0,1085,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Дай бог тебе! Но как же удалось вам",0,1085,0,0],["v","Прогнать врага от городских ворот",0,1086,0,0],["v","И сохранить ограду невредимой?",0,1087,0,0],["v","Скажи скорей, чтоб я могла слепцу",0,1088,0,0],["v","Нежданное поведать избавленье.",0,1089,0,0],["sp","Вестник"],["v","Там, в вышине, отважный <span class=\"ch\" data-ch=\"menekey\">Менекей</span>,",0,1090,0,1],["v","За родину мечом пронзая горло,",0,1090,0,0],["v","Готовил нам спасенье, а внизу",0,1091,0,0],["v","Твой сын делил фиванцев на отряды,",0,1092,0,0],["v","Чтоб семь ворот удобней охранять.",0,1093,0,0],["v","Он конницу поставил против конных,",0,1094,0,0],["v","Пехоту к пехотинцам пригонял,",0,1095,0,0],["v","Со всех сторон готовясь встретить приступ.",0,1096,0,0],["v","Я с башни был поставлен наблюдать.",0,1097,0,0],["v","Смотрю — вдали, на высотах Тевмесских,",0,1098,0,0],["v","Какое-то движенье: вот щиты,",0,1099,0,0],["v","Белеяся, сплотились, вот аргосцев",0,1100,0,1],["v","Огромная бегущая толпа",0,1100,0,0],["v","Становится все ближе, все виднее",0,1101,0,0],["v","И — прямо к нам, на стены: только ров",0,1102,0,0],["v","Остановил их бурное движенье…",0,1102,0,0],["v","И вот зараз и с наших стен, и там",0,1103,0,0],["v","Призывные пеаны зазвучали",0,1104,0,0],["v","И заиграли трубы. Впереди",0,1105,0,0],["v","Своих рядов, щетинистых и плотных,",0,1105,0,0],["v","На ворот<em>а</em> Неитские держал",0,1106,0,0],["v","Парафенопей, и щит его девизом",0,1107,0,0],["v","Кабана этолийского имел,",0,1107,0,0],["v","Сраженного стрелою Аталанты…",0,1108,0,0],["v","А там в воротах Прета я увидел",0,1109,0,0],["v","Амфиарая вещего — он вез",0,1110,0,1],["v","На колеснице жертвенных животных,",0,1111,0,0],["v","И скромный щит героя не блистал",0,1112,0,0],["v","Эмблемами надменными. К воротам,",0,1113,0,0],["v","Что Старыми зовутся, подвигался",0,1114,0,0],["v","Гиппомедонт, и щит его тяжелый,",0,1115,0,0],["v","Стооким Аргусом украшенный, пестрел,",0,1116,0,0],["v","А ворота Гомола ожидали",0,1117,0,0],["v","Тидея с шкурой львиной на щите,",0,1120,0,1],["v","И волоса на ней вздымались грозно;",0,1120,0,0],["v","Десница же Тидеева несла",0,1121,0,0],["v","В светильнике губительное пламя,",0,1122,0,0],["v","Как нес его когда-то Прометей.",0,1123,0,0],["v","На ворота Источника грозою<a class=\"nr\" href=\"#n-k56\" data-n=\"k56\" aria-label=\"Примечание 56\">56</a>",0,1124,0,0],["v","Шел <span class=\"ch\" data-ch=\"polinik\">Полиник</span>, твой сын, и щит его",0,1125,0,0],["v","Потнийскими конями был украшен,",0,1125,0,0],["v","И ужасом исполнились сердца,",0,1126,0,0],["v","Когда коней беситься он заставил,",0,1127,0,0],["v","Их двигая искусно за щитом.",0,1128,0,0],["v","А против врат Электриных воздвигся",0,1129,0,0],["v","С дружиною надменный Капаней,",0,1130,0,1],["v","Себя богам безумно приравнявший;",0,1130,0,0],["v","Щит украшал ему литой гигант:",0,1131,0,0],["v","Какой-то город снявши с оснований,",0,1132,0,0],["v","Он на плечи себе его взвалил, —",0,1133,0,0],["v","И то была угроза нашим Фивам!",0,1133,0,0],["v","У врат седьмых был, наконец, Адраст…",0,1134,0,0],["v","Аргосский щит украшен был рисунком,",0,1135,0,0],["v","Изображавшим Гидру, вкруг нее",0,1136,0,0],["v","Сто лютых змей вилися, и драконы",0,1136,0,0],["v","С кадмейских стен похищенных бойцов",0,1137,0,0],["v","В своих кровавых челюстях держали —",0,1138,0,0],["v","Микенская утеха! Таковы",0,1139,0,0],["v","Моим <em>тогда</em> вожди предстали взорам…",0,1140,0,1],["v","Наш первый бой был бой издалека,<a class=\"nr\" href=\"#n-k55\" data-n=\"k55\" aria-label=\"Примечание 55\">55</a>",0,1140,0,0],["v","Перо стрелы, и тяжкие обломки,",0,1141,0,0],["v","И дротики из напряженных рук,",0,1141,0,0],["v","И из пращи сокрытый меткий камень —",0,1142,0,0],["v","Все было нам защитою… Но вот",0,1142,0,0],["v","Тидей, когда одолевать мы стали,",0,1143,0,0],["v","Так закричал аргосцам, а за ним",0,1144,0,0],["v","Твой <span class=\"ch\" data-ch=\"polinik\">Полиник</span>, царица: \"О данайцы!",0,1144,0,0],["v","Не ждете ль вы, чтоб перебили вас",0,1145,0,0],["v","Снарядами? Что медлите набегом",0,1145,0,0],["v","Ворота взять? За мной, вперед, гимнеты!<a class=\"nr\" href=\"#n-k57\" data-n=\"k57\" aria-label=\"Примечание 57\">57</a>",0,1146,0,0],["v","И конные, и с колесниц своих",0,1147,0,0],["v","Из-за щитов разящие гоплиты!\"",0,1147,0,0],["v","На этот зов аргосцы, как один,",0,1148,0,0],["v","Все поднялись, и кровью обагрился",0,1148,0,0],["v","Из черепов разбитых вражий стан…",0,1149,0,0],["v","Не раз тогда и с наших стен летели",0,1150,0,1],["v","Убитые, как ловкий акробат,",0,1151,0,0],["v","И на поля их кровь лилась потоком…",0,1152,0,0],["v","Но вот из уст аркадских слышен крик:",0,1153,0,0],["v","«Огня сюда и топоров!» И вижу",0,1154,0,0],["v","У самых стен исчадье Аталанты…",0,1155,0,0],["v","Ворота он ломать готов, но камнем",0,1156,0,0],["sd","(Которого в повозке не свезти)"],["v","В него метнул Периклимен с забрала, —",0,1157,0,0],["v","И голова под золотом кудрей",0,1158,0,0],["v","Размозжена, по швам своим расселась,",0,1159,0,0],["v","А щек его румянец заалел",0,1160,0,1],["v","От хлынувшей из раны крови жаркой;",0,1160,0,0],["v","И дочь Меналова, царица стрел, увы,",0,1161,0,0],["v","Живого сына больше не увидит…<a class=\"nr\" href=\"#n-k58\" data-n=\"k58\" aria-label=\"Примечание 58\">58</a>",0,1162,0,0],["v","Обрадован удачею, наш царь",0,1162,0,0],["v","К другим спешит воротам. <span class=\"ch\" data-ch=\"eteokl\">Этеоклов</span>",0,1163,0,0],["v","Я правлю след. Глядим, у наших стен",0,1164,0,0],["v","Тидей орудует с дружиной этолийской,",0,1165,0,0],["v","А меткий их и непрерывный дротик,",0,1165,0,0],["v","Того гляди, что башенный карниз",0,1166,0,0],["v","Снесет… Уж, тыл к Тидею обращая,",0,1167,0,0],["v","Покинуть пост дерзнули сторожа",0,1167,0,0],["v","И за стеной от гибели спасались,",0,1168,0,0],["v","Когда сам царь на бруствер их вернул,",0,1169,0,0],["v","Как псов труба охотничья сзывает…",0,1170,0,1],["v","Мы — далее… О, ужас! Капаней…",0,1171,0,0],["v","Нет, ярости надменной не сумею",0,1172,0,0],["v","Я передать, с которой сходни он",0,1173,0,0],["v","Огромные влачил к фиванским стенам",0,1174,0,0],["v","И с похвальбой кричал, что сам Зевес",0,1175,0,0],["v","Не защитит теперь кадмейских башен.",0,1176,0,0],["v","И вот уже по гладким ступеням",0,1177,0,0],["v","Взбирается, и град камней тяжелых",0,1178,0,0],["v","Принять на щит тяжелый норовит…",0,1179,0,0],["v","Вот гребень стен перешагнуть готов он…",0,1180,0,1],["v","И вдруг… Зевес ударом поразил",0,1181,0,0],["v","Безумного… Далеко задрожала",0,1182,0,0],["v","Земля окрест, и, тяжестью своей",0,1183,0,0],["v","Влекомый, он упал сожженным трупом.",0,1184,0,0],["v","Кронидов гнев аргосского царя",0,1185,0,0],["v","В смущение приводит, и дружины",0,1186,0,0],["v","Он отозвать спешит, но на врага",0,1187,0,0],["v","Нежданные кидаются фиванцы,",0,1188,0,0],["v","Зевесовым огнем ободрены…",0,1189,0,0],["v","Все хлынуло из города — пехота,",0,1190,0,1],["v","И всадники, и сотни колесниц",0,1191,0,0],["v","Среди врагов измятых очутились,",0,1192,0,0],["v","И копья Фив вонзились в их щиты.",0,1193,0,0],["v","Разгром полнейший! Сколько там убитых,",0,1194,0,0],["v","Что колесниц поверженных, колес",0,1195,0,0],["v","Что разлетелось в щепки! Все смешалось:",0,1196,0,0],["v","И трупы и обломки. Да, пока",0,1197,0,0],["v","Мы отстоять сумели укрепленья,",0,1198,0,0],["v","А что потом случится, знает бог…",0,1199,0,0],["sd","(Подавляя вздох.)"],["sp","Корифей"],["v","О, победить отрадно: разве боги",0,1200,0,1],["v","Что лучшее придумают, не мы.",0,1200,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Ко мне судьба и боги благосклонны:",0,1201,0,0],["v","И сыновья живут, и город цел,",0,1202,0,0],["v","А <span class=\"ch\" data-ch=\"menekey\">Менекей</span> погибший — это кара",0,1203,0,0],["v","Его отцу за мой преступный брак",0,1204,0,0],["v","И тяжесть мук Эдиповых. Он может",0,1205,0,0],["v","Утешиться, конечно, благом Фив…",0,1206,0,0],["v","Но ты вернись к начатому… Что дальше?",0,1207,0,0],["v","Что стали делать дальше сыновья?",0,1208,0,0],["sp","Вестник"],["v","Будь счастлива, царица, тем, что есть.",0,1209,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Я знать хочу, что было дальше, вестник…",0,1210,0,1],["sp","Вестник"],["v","Иль весть тебе спасенья не мила?",0,1210,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Грядущее безвестностью тревожит…",0,1211,0,0],["sp","Вестник"],["v","Позволь уйти, царица, <em>дело</em> ждет:",0,1212,0,0],["v","<em>Царю</em> его оруженосец <em>нужен</em>.",0,1212,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["dir","пытливо всматриваясь в него"],["v","Ты от меня несчастие таишь?..",0,1213,0,0],["sp","Вестник"],["v","Ох, продолжать-то лучше бы не надо…",0,1214,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["dir","вцепляясь в него"],["v","Ты скажешь все, коли тебя в эфир",0,1215,0,0],["v","Не унесут невидимые крылья…",0,1215,0,0],["sp","Вестник"],["v","О, горе мне! Зачем благую весть",0,1216,0,0],["v","Принесшего уйти ты не пустила?",0,1217,0,0],["v","Внемли же злу, царица, и узнай,",0,1217,0,0],["v","<em>Что сыновья твои в единоборство</em> —",0,1218,0,0],["sd","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span> с легким стоном делает шаг назад и закрывает лицо руками."],["v","О, дерзость, о, неслыханный позор! —",0,1219,0,0],["v","Теперь вступить готовятся отдельно",0,1220,0,1],["v","От воинов, и громогласных слов",0,1220,0,0],["v","Им возвратить уже не может воздух…",0,1221,0,0],["v","Когда к молчанию воззвал глашатай",0,1222,0,0],["v","И все ряды затихли в ожиданье,",0,1223,0,0],["v","С высокой башни первым <span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>",0,1224,0,0],["v","Речь обратил к соперникам затихшим…",0,1225,0,0],["v","\"Данайцев цвет и ты, народ кадмейский,",0,1226,0,0],["v","Так говорил наш юный властелин, —",0,1227,0,0],["v","Из-за меня и брата <span class=\"ch\" data-ch=\"polinik\">Полиника</span>",0,1228,0,0],["v","Довольно жертв. Я сам себя хочу",0,1229,0,0],["v","Отстаивать, и пусть единоборство",0,1230,0,1],["v","Сегодня спор меж братьями решит.",0,1231,0,0],["v","Убив, царить я буду безраздельно,",0,1232,0,0],["v","Осиленный, я отдаю престол.",0,1233,0,0],["v","А вам, мужи аргосские, не лучше ль",0,1234,0,0],["v","В отчизне жить, чем в Фивах умирать?\"",0,1235,0,0],["v","Так он сказал, и брат, ряды покинув,",0,1236,0,0],["v","Его слова хвалою увенчал,",0,1237,0,0],["v","Ему вослед враги рукоплескали,",0,1238,0,0],["v","И гул со стен их правыми признал…",0,1239,0,0],["v","Был тотчас мир объявлен, и клянутся",0,1240,0,1],["v","Торжественно хранить его вожди.",0,1240,0,0],["v","Потом одеть бойцов блестящей медью",0,1241,0,0],["v","К шатрам птенцов <span class=\"ch\" data-ch=\"edip\">Эдипа</span> собрались,",0,1242,0,0],["v","И одного потомки спартов древних,",0,1243,0,0],["v","Данайцев цвет другого окружил.",0,1244,0,0],["v","И вот на бой сошлись они, сияя.",0,1245,0,0],["v","С их юных лиц румянец не сбегал,",0,1246,0,0],["v","У каждого горело сердце только",0,1247,0,0],["v","Скорей копье в соперника метнуть…",0,1248,0,0],["v","Окрест друзья, словами ободряя,",0,1249,0,0],["v","Твердили им: \"Могучий <span class=\"ch\" data-ch=\"polinik\">Полиник</span>,",0,1250,0,1],["v","Ты, победив, трофей поставишь Зевсу,",0,1250,0,0],["v","А в Аргосе легендой станешь ты!\",",0,1251,0,0],["v","\"О, Этеокл, отчизну защищая,",0,1252,0,0],["v","Победою венчаешь ты престол!\".",0,1252,0,0],["v","И жар сильней в их душах разгорался.",0,1253,0,0],["v","Гадатели ж, проливши кровь ягнят,",0,1254,0,0],["v","Дым жертвенный прилежно наблюдали:",0,1255,0,0],["v","Развеется или столбом пойдет,",0,1255,0,0],["v","И по тому, высоко ль пламя жертвы,",0,1256,0,0],["v","И на кипящей влаге пузыри, —",0,1257,0,0],["v","Грядущего исход вещали боя…",0,1257,0,0],["v","О, если ты их можешь удержать",0,1258,0,0],["v","Иль силою, иль хитрыми речами,",0,1259,0,0],["v","Иль чарами, молю тебя, не медли,",0,1260,0,1],["v","Иди туда, Иокаста, и детей",0,1260,0,0],["v","Останови средь пагубного боя…",0,1261,0,0],["sd","(Уходит.)"],["scene","Явление четырнадцатое","s18",5,18],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["dir","обращаясь к терему"],["v","Покинь чертог, дитя мое, и к нам",0,1262,0,0],["v","Сойди скорей! Тебе готовят боги",0,1263,0,0],["v","Не терема девичьего покой,",0,1264,0,0],["v","Не хоровод с подругами веселый:",0,1265,0,0],["v","Ты с матерью мольбами разнимать",0,1266,0,0],["v","Пойдешь сейчас ужасный поединок",0,1267,0,0],["v","Двух витязей, твоих несчастных братьев.",0,1268,0,0],["v","Голос <span class=\"ch\" data-ch=\"antigona\">Антигоны</span>",0,1269,0,0],["v","О мать моя, ужель еще удар",0,1270,0,1],["v","Мне голос твой призывный возвещает?",0,1270,0,0],["sd","(Выходит из ворот.)"],["scene","Явление пятнадцатое","s19",5,19],["v","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span> и <span class=\"ch\" data-ch=\"antigona\">Антигона</span>.",0,1271,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Их нет, о дочь, нет братьев у тебя.",0,1272,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Что говоришь?!",0,1273,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Они на поединке…",1,1273,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Что ж делать мне?",0,1274,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Идти туда со мной.",1,1274,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Из терема?!",0,1275,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["dir","тащит ее"],["v","Туда, на поле брани…",1,1275,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Мне стыдно, мать!",0,1276,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","О, до того ль теперь!",1,1276,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Чем помогу?",0,1277,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Ты прекратишь их ссору.",1,1277,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Но чем, скажи?",0,1278,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Мы будем их молить…",1,1278,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Идем же, мать… О, для чего мы медлим!..",0,1279,0,0],["sp","<span class=\"ch\" data-ch=\"iokasta\">Иокаста</span>"],["v","Да, да, скорей! И если там живых",0,1280,0,1],["v","Застанем мы, я буду видеть солнце,",0,1281,0,0],["v","Но трупы их похорони со мной.",0,1282,0,0],["v","Уходят поспешно.",0,1283,0,0],["scene","Четвертый музыкальный антракт","s20",5,20],["sp","Хор"],["str","Строфа"],["v","Увы! Увы!",0,1284,2,0],["v","Дрожит мое сердце тоскою и страхом!",0,1285,0,0],["v","И к матери горькой",0,1286,2,0],["v","Глубокая жалость любви",0,1287,2,0],["v","Суставы мои проницает…",0,1288,2,0],["v","О Зевс, о матерь-Земля,",0,1290,2,1],["v","О бедствия тягость!",0,1290,2,0],["v","Который, который из них,",0,1291,2,0],["v","Кровию брата обрызган,",0,1292,2,0],["v","Через доспех и одежды",0,1292,2,0],["v","Братскую душу погасит",0,1293,2,0],["v","И слезы пролью над которым,",0,1294,0,0],["v","Тяжелые слезы разлуки?",0,1295,0,0],["str","Антистрофа"],["v","Увы! Увы!",0,1295,2,0],["v","Как звери, со злобой в душе кровожадной,",0,1296,0,0],["v","Копьем потрясая,",0,1297,2,0],["v","Уж прянуть готовы они",0,1297,2,0],["v","За свежею вражьею кровью…",0,1298,2,0],["v","Зачем, скажите, зачем",0,1299,2,0],["v","Ваш бой одиночный?",0,1300,2,1],["v","Напевом родных берегов",0,1301,2,0],["v","Я обовью ваши беды…",0,1302,2,0],["v","Стонами мертвых оплачу…",0,1303,2,0],["v","Близок конец неизбежный,",0,1304,2,0],["v","И меч порешит вашу ссору,",0,1305,0,0],["v","О горькие жертвы Эриний!",0,1306,0,0],["sp","Корифей"],["v","Но вот <span class=\"ch\" data-ch=\"kreont\">Креонт</span>, с своей печалью тяжкой:",0,1307,0,0],["v","Не надо плакать, сестры, перед ним…",0,1308,0,0],["act","Действие пятое","a6","V"],["scene","Явление шестнадцатое","s21",6,21],["v","Креонт, за ним слуги несут тело <span class=\"ch\" data-ch=\"menekey\">Менекея</span>.",0,1309,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","О, горе мне! Кому пошлю вас, стоны,",0,1310,0,1],["v","Из уст моих летящие, и вас,",0,1310,0,0],["v","Потоки слез? Себя ли я оплачу,",0,1311,0,0],["v","Иль город мой, увитый тучей скорби",0,1312,0,0],["v","И Ахеронт узревший?.. Этот труп",0,1313,0,0],["v","Погибшего такою благородной",0,1314,0,0],["v","И для меня такою тяжкой смертью,",0,1315,0,0],["v","Самоубийцы труп я подобрал",0,1315,0,0],["v","На самом дне Драконовой пещеры;",0,1316,0,0],["v","Сестре моей отдам его, и пусть",0,1317,0,0],["v","Племянника омоет и оденет,",0,1318,0,0],["v","Чело его цветами уберет…",0,1319,0,0],["v","Кто жив еще, услугой бездыханным",0,1320,0,1],["v","Царя глубин подземных да почтит!..",0,1320,0,0],["sd","(Направляется к дому.)"],["v","Тело уносят.",0,1321,0,0],["sp","Корифей"],["v","Твоей сестры в чертоге нет, вельможный,",0,1322,0,0],["v","Она ушла, и <span class=\"ch\" data-ch=\"antigona\">Антигона</span> с ней.",0,1323,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Ушли? Куда? Какой судьбе покорны?",0,1324,0,0],["sp","Корифей"],["v","К ней весть пришла, что сыновья ее",0,1325,0,0],["v","В борьбе за трон на поединок вышли.",0,1325,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Что говоришь?.. Услуги мертвецу",0,1326,0,0],["v","Любимому последние, и эти",0,1327,0,0],["v","Слова ужасные и новые… о нет…",0,1328,0,0],["sp","Корифей"],["dir","видя подходящего вестника"],["v","Увы, Креонт, твоя сестра ушла",0,1329,0,0],["v","Давно… и роковой конец, наверно,",0,1330,0,1],["v","Принять успел их бой ожесточенный.",0,1330,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Да, ты права… И мрачен и уныл",0,1331,0,0],["v","Вид воина, идущего оттуда…",0,1332,0,0],["v","Какая весть в устах твоих, гонец?",0,1333,0,0],["scene","Явление семнадцатое","s22",6,22],["v","<span class=\"ch\" data-ch=\"kreont\">Креонт</span> и вестник.",0,1334,0,0],["sp","Вестник"],["v","О, горе мне… Рассказывать иль плакать?",0,1335,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Ужасное начало! Мы погибли.",0,1336,0,0],["sp","Вестник"],["v","Горе, и двойное горе… Тяжек груз фиванских бед.",0,1337,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Старых, старых или новых? Не задерживай ответ..",0,1338,0,0],["sp","Вестник"],["v","Узнай… они не видят больше солнца…<a class=\"nr\" href=\"#n-k59\" data-n=\"k59\" aria-label=\"Примечание 59\">59</a>",0,1339,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","О, боже мой!",0,1340,0,1],["v","Жестокие, ужасные слова!",0,1340,0,0],["v","Так вот они, Эдиповы проклятья,",0,1341,0,0],["v","Ты слышишь ли, свидетель их — чертог?..",0,1342,0,0],["sp","Корифей"],["v","Он нем и только потому не плачет…",0,1343,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","О, горе мне! О, тягость наших бед,",0,1344,0,0],["v","О, город мой, о, злополучный город!",0,1345,0,0],["sp","Вестник"],["v","Еще не все… Ты дальше не слыхал…",0,1346,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Да что же скажешь ты еще ужасней?",0,1347,0,0],["sp","Вестник"],["v","Твоей сестры <span class=\"ch\" data-ch=\"iokasta\">Иокасты</span> тоже нет…",0,1348,0,0],["v","<span class=\"ch\" data-ch=\"kreont\">Креонт</span> молча закрывает глаза краем гиматия.",0,1349,0,0],["sp","Корифей"],["v","Оплачь ее, оплачь ее со мною,",0,1350,0,1],["v","Руками белыми лицо терзай…",0,1350,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Прости меня, Иокаста, жизни горькой",0,1351,0,0],["v","И грешного узревшая предел",0,1352,0,0],["v","Загадкою дарованного брака…",0,1353,0,0],["sd","(На несколько секунд остается погруженным в размышление и воспоминания, потом поднимает голову с сухими глазами.)"],["v","Но, клятвою <span class=\"ch\" data-ch=\"edip\">Эдипа</span> порожден,",0,1353,0,0],["v","Каков же был тот братский поединок?",0,1354,0,0],["v","Поведай нам, о вестник новых бед…",0,1355,0,0],["sp","Вестник"],["v","Пред башнями кадмейскими победу",0,1356,0,0],["v","Прияли мы от Зевса; это ты,",0,1356,0,0],["v","Конечно, уж узнал, <span class=\"ch\" data-ch=\"kreont\">Креонт</span>: в чертоги",0,1357,0,0],["v","С фиванских стен для вести близок путь.",0,1358,0,0],["v","Когда, тела одев блестящей медью,",0,1359,1,0],["v","Меж двух дружин сошлися сыновья",0,1360,0,1],["v","Эдиповы на спор и бой копейный,",0,1360,0,0],["v","Взор обратя к Микенам, Политик",0,1361,0,0],["v","Так говорил с мольбою к властной Гере:",0,1362,0,0],["v","\"Владычица, я твой с тех самых пор,",0,1363,0,0],["v","Как, в жены взяв аргосскую царевну,",0,1364,0,0],["v","В земле твоей я поселился жить:",0,1365,0,0],["v","Соперника и брата уничтожить",0,1365,0,0],["v","Ты помоги мне, Гера, и вручи<a class=\"nr\" href=\"#n-k60\" data-n=\"k60\" aria-label=\"Примечание 60\">60</a>",0,1366,0,0],["v","Мне кровию омытую победу\".",0,1367,0,0],["v","Да, <span class=\"ch\" data-ch=\"polinik\">Полиник</span> и жаждал и молил",0,1368,0,0],["v","Позорного венца братоубийцы.",0,1369,0,0],["v","⟨И многие заплакали украдкой,",0,1370,0,1],["v","Стараясь друг от друга слезы скрыть.⟩",0,1371,0,0],["v","А <span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>, остановив глаза",0,1372,0,0],["v","На алтаре Паллады златощитной,",0,1373,0,0],["v","Молился так: \"О Зевсово дитя,",0,1374,0,0],["v","Победою копье венчая, брату",0,1375,0,0],["v","Направь его, богиня, прямо в грудь,",0,1376,0,0],["v","И пусть убьет предателя отчизны\".",0,1377,0,0],["v","Едва сказал, и ярче, чем огонь,",0,1378,0,0],["v","Им медь трубы сигналом зазвучала.",0,1379,0,0],["v","И вот, с оскалом вепря на устах",0,1380,0,1],["v","И с пеною на искаженных лицах,",0,1380,0,0],["v","Сбегаются, — и прянуло копье,",0,1381,0,0],["v","Но в тот же миг щиты обоих скрыли,",0,1382,0,0],["v","И даром медь по глади их скользит…",0,1383,0,0],["v","Но, зоркие глаза к щиту приставив,",0,1383,0,0],["v","В сопернике соперник уловить",0,1384,0,0],["v","Старается чела свободный угол…",0,1385,0,0],["v","И кружатся безмолвные враги,",0,1386,0,0],["v","В руке копье бессильное сжимая…",0,1386,0,0],["v","Нас, зрителей, из страха за своих",0,1387,0,0],["v","Тут даже в пот ударило, но сами",0,1388,0,0],["v","Усталости не ведали бойцы…",0,1389,0,0],["v","Вот <span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>, ногой нащупав камень,",0,1390,0,1],["v","Его с пути отбросить захотел,",0,1391,0,0],["v","Но в тот же миг в лодыжке перебитой",0,1392,0,0],["v","Он братское почувствовал копье, —",0,1393,0,0],["v","И в радости данайцы завопили.",0,1394,0,0],["v","Тогда наш царь, перемогая боль,",0,1395,0,0],["v","В открытое плечо наметил брату,",0,1396,0,0],["v","Но не попал — сломилось острие…",0,1397,0,0],["v","Он шаг назад и камнем <span class=\"ch\" data-ch=\"polinik\">Полинику</span>",0,1398,0,0],["v","Древко копья ломает пополам:",0,1400,0,1],["v","И вновь они равны и беззащитны…",0,1401,0,0],["v","Черед настал для боевых мечей.",0,1402,0,0],["v","Но, обнажив тяжелое железо,",0,1403,0,0],["v","Из-за щитов сначала не могли",0,1404,0,0],["v","Они вредить друг другу — только стук",0,1405,0,0],["v","Да гул стоял окрест от их ударов…",0,1406,0,0],["v","Пока наш царь в уме не воскресил",0,1407,0,0],["v","В Фессалии им виденную хитрость:",0,1408,0,0],["v","Осев на ногу левую, свой щит",0,1410,0,1],["v","Приподнял он, и правой сделал выпад,",0,1410,0,0],["v","А так как враг при этом не успел,",0,1411,0,0],["v","Подвинув щит, закрыться от удара,",0,1412,0,0],["v","Ему в живот уходит лезвие…",0,1413,0,0],["v","Тот падает на землю, кровь ручьями",0,1414,0,0],["v","Из раны хлынула, а победитель-царь,",0,1415,0,0],["v","Считая бой оконченным, бросает",0,1415,0,0],["v","Кровавый меч и голою рукой",0,1416,0,0],["v","Доспех снимать с поверженного брата",0,1417,0,0],["v","Нагнулся, щит оставив на земле…",0,1418,0,0],["v","Но <span class=\"ch\" data-ch=\"polinik\">Полиник</span> и лежа меч тяжелый",0,1419,0,0],["v","Еще сжимал хладеющей рукой…",0,1420,0,1],["v","Отчаянным усилием железо",0,1420,0,0],["v","Приподнял он и, торжество прервав,",0,1421,0,0],["v","Вонзил его ликующему в сердце…",0,1422,0,0],["v","Враги теперь в смешавшейся крови",0,1422,0,0],["v","Лежат, и пыль уста их покрывает,",0,1423,0,0],["v","И мощно смерть соединила их —",0,1424,0,0],["v","Непобедившего с непобежденным.",0,1425,0,0],["sp","Корифей"],["v","Увы! Увы! О, бедствия слепца",0,1425,0,0],["v","И ты, о мощь отцовского проклятья!",0,1426,0,0],["v","В хоре плач.",0,1427,0,0],["sp","Вестник"],["v","Но погоди… Я не исчерпал бед…",0,1427,0,0],["v","Когда бойцы бессильно землю грызли",0,1428,0,0],["v","И смерть уже глядела им в глаза,",0,1429,0,0],["v","Явилась мать-царица… Эти раны,",0,1430,0,1],["v","И кровь, и смертные мучения детей",0,1430,0,0],["v","Увидела несчастная, и вопли",0,1431,0,0],["v","Тяжелые по полю понеслись.",0,1431,0,0],["v","\"Зачем, — она взывает, — я не знала",0,1432,0,0],["v","О вашем бое, дети, и разнять",0,1432,0,0],["v","Вас не пришла? Зачем теперь уж поздно?\"",0,1433,0,0],["v","То к одному со стоном припадет,",0,1433,0,0],["v","То над другим, рыдая, причитает:",0,1434,0,0],["v","Ей вспомнились и муки и труды,",0,1434,0,0],["v","Что выпали на долю ей напрасно,",0,1435,0,0],["v","И ласки ей припомнились. А дочь —",0,1435,0,0],["v","Царевна так в слезах им говорила:",0,1436,0,0],["v","\"Кормильцы матери, опора старика,",0,1436,0,0],["v","О, на кого меня вы, сиротинку,",0,1437,0,0],["v","Покинули, без мужа и семьи?\"",0,1437,0,0],["v","Царь <span class=\"ch\" data-ch=\"eteokl\">Этеокл</span> среди мучений смертных",0,1438,0,0],["v","Мать узнает, но, влажною рукой",0,1438,0,0],["v","Ее лица касаясь, он не может",0,1439,0,0],["v","Произнести ни слова. Только глаз",0,1440,0,1],["v","Немая речь родимую ласкает…",0,1440,0,0],["v","А <span class=\"ch\" data-ch=\"polinik\">Полиник</span> еще дышал, и, мать",0,1441,0,0],["v","С сестрою глаз лучами обливая,",0,1442,0,0],["v","Он им сказал: \"Простите… жизни нет",0,1443,0,0],["v","В твоем ребенке, мама, и жалею",0,1444,0,0],["v","Я очень и тебя, и <span class=\"ch\" data-ch=\"antigona\">Антигону</span>,",0,1445,0,0],["v","И <span class=\"ch\" data-ch=\"eteokl\">Этеокла</span> тоже — бедный брат!",0,1445,0,0],["v","Он был мой враг, но умирает братом…",0,1446,0,0],["v","Смотри же, мать, и ты, сестра, мой труп",0,1447,0,0],["v","Похороните дома… вы фиванцев",0,1448,0,0],["v","Упросите? Не правда ли? Из царства,",0,1449,0,0],["v","Которого лишился я, земли",0,1450,0,1],["v","У них прошу ничтожные две горсти…",0,1450,0,0],["v","Дай руку, мать… глаза мои закрой…\"",0,1451,0,0],["v","И у него еще достало силы",0,1452,0,0],["v","Ее рукой коснуться век своих",0,1452,0,0],["v","И прошептать: \"Простите… мрак могильный",0,1453,0,0],["v","Мои глаза наполнил… О, прости…\"",0,1454,0,0],["v","Сказал — и жизнь несчастнейшие братья",0,1455,0,0],["v","Покинули в один и тот же миг…",0,1455,0,0],["v","А мать в порыве ужаса и муки",0,1456,0,0],["v","Из трупа меч кровавый извлекла",0,1457,0,0],["v","И в грудь всадила, после зашаталась,",0,1457,0,0],["v","Вся белая, упала меж детей",0,1458,0,0],["v","И умерла, их молча обнимая…",0,1459,0,0],["v","Меж тем вокруг уж разгорался спор,",0,1460,0,1],["v","Кто победил, и мы за <span class=\"ch\" data-ch=\"eteokl\">Этеокла</span>,",0,1460,0,0],["v","Данайцы против были. А вожди",0,1461,0,0],["v","Решить сомнений наших не умели…",0,1462,0,0],["v","Тот тени <span class=\"ch\" data-ch=\"polinik\">Полиника</span> присуждал",0,1463,0,0],["v","Победу за его удар начальный,",0,1463,0,0],["v","А тот совсем победы не хотел",0,1464,0,0],["v","В бою искать, где оба — бездыханны…",0,1465,0,0],["v","Спор перешел в ожесточенный крик:",0,1466,0,0],["v","«К оружию!» И счастье улыбнулось",0,1466,0,0],["v","На этот раз фиванцам — мы щитов",0,1467,0,0],["v","Не бросили, пока кипели споры, —",0,1468,0,0],["v","Враг мигом смят, и ни один данаец",0,1469,0,0],["v","Не устоял — убитых горы там,",0,1470,0,1],["v","Наводнена долина кровью вражьей,",0,1470,0,0],["v","Немногие успели убежать.",0,1471,0,0],["v","Теперь одни трофей Крониду ставят —",0,1472,0,0],["v","Из золота Зевесов истукан,",0,1472,0,0],["v","Другие же, сорвав доспехи вражьи,",0,1473,0,0],["v","Ликуя, их в Кадмею повлекли.",0,1474,0,0],["v","И наконец, с царевной <span class=\"ch\" data-ch=\"antigona\">Антигоной</span>",0,1475,0,0],["v","Последние, подняв на рамена,",0,1475,0,0],["v","Сюда несут трех горьких мертвецов.",0,1476,0,0],["v","Да примут их друзья и здесь оплачут.",0,1477,0,0],["v","Таков исход законченной борьбы,",0,1477,0,0],["v","Для города счастливый и ужасный.",0,1478,0,0],["act","Исход","a7",""],["sp","Хор"],["v","Увы! Увы!",0,1479,0,0],["v","Не слова нам приносят печаль,",0,1480,0,1],["v","И <span class=\"ch\" data-ch=\"edip\">Эдипов</span> чертог",0,1480,0,0],["v","Черной ризою кроют не речи.",0,1481,0,0],["scene","Явление восемнадцатое","s23",7,23],["v","Те же. <span class=\"ch\" data-ch=\"antigona\">Антигона</span> и толпа.",0,1481,0,0],["sd","Показывается процессия: впереди идет <span class=\"ch\" data-ch=\"antigona\">Антигона</span>, с пеплосом, спущенным с одного плеча, горящими глазами и волосами, выбившимися из-под фаты; за ней толпа несет три одра с мертвыми, <span class=\"ch\" data-ch=\"eteokl\">Этеокла</span> впереди. Когда их ставят, то мать помещают у сыновей в головах."],["sp","Хор"],["v","Вот они… глядите, глядите…",0,1482,0,0],["v","К очагу родному вернулись!",0,1483,0,0],["v","Трое из вкусивших от мрака,",0,1483,0,0],["v","Крепко связанных общей смертью.<a class=\"nr\" href=\"#n-k61\" data-n=\"k61\" aria-label=\"Примечание 61\">61</a>",0,1484,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Под фатою своей девичьей",0,1485,2,0],["v","Я румяных щек не таила,<a class=\"nr\" href=\"#n-k62\" data-n=\"k62\" aria-label=\"Примечание 62\">62</a>",0,1485,2,0],["v","Нежный локон по воле развился, —",0,1486,2,0],["v","И смотрели люди, дивились…",0,1486,2,0],["v","Точно зельем каким напоила",0,1487,2,0],["v","Злая смерть вакханку печали,",0,1488,2,0],["v","Что огнем горят погребальным",0,1488,2,0],["v","У вакханки пьяные очи",0,1489,2,0],["v","И с плеча спустился шафранный,",0,1490,2,1],["v","У безумной, девичий пеплос…",0,1490,2,0],["v","Что бежит, а за нею трупы.",0,1491,2,0],["v","Ты, Полиник, врагом наречен недаром, недаром:",0,1492,0,0],["v","Распря твоя вражду родила, и смерти, и смерти.",0,1493,0,0],["v","Дом <span class=\"ch\" data-ch=\"edip\">Эдипов</span> она потопила в крови,",0,1494,0,0],["v","В страшной крови, в нечестивой крови.",0,1495,0,0],["v","Увы! Увы!",0,1495,2,0],["v","Для стонов моих",0,1496,2,0],["v","Найду ли мелодии звуки?",0,1497,2,0],["v","Флейту найду ль или бубен?",0,1498,2,0],["v","И кто оплачет со мной",0,1499,3,0],["v","В чертогах, в чертогах",0,1500,3,1],["v","Утеху Эриний,",0,1500,3,0],["v","Три трупа, три трупа?",0,1501,3,0],["v","Сгубила, богиня, сгубила",0,1502,2,0],["v","И дом и <span class=\"ch\" data-ch=\"edip\">Эдипа</span>",0,1503,2,0],["v","За то, что загадки",0,1504,2,0],["v","Мудреную тайну,",0,1505,2,0],["v","Разумный, решил он.",0,1505,2,0],["v","Увы мне! Увы мне! Увы мне!",0,1506,2,0],["v","Отец, отец,",0,1507,4,0],["v","Кто раньше вельможный —",0,1508,3,0],["v","Иль варвар, иль эллин —",0,1509,3,0],["v","От зол столь великих",0,1510,3,1],["v","Столь явные беды",0,1510,3,0],["v","Под солнцем изведал?",0,1511,3,0],["v","Я пойду в зеленую рощу,",0,1512,2,0],["v","Буду взором бродить, тоскуя,",0,1513,2,0],["v","По дубовой чаще да елям,",0,1514,2,0],["v","Не найду ли птицы печальной,",0,1515,2,0],["v","У которой птенцов отобрали…",0,1516,2,0],["v","Пусть своею трелью со мною,",0,1517,2,0],["v","Своей жалобной трелью плачет!..",0,1518,2,0],["v","⟨Жалобной песней и стоном",0,1519,2,0],["v","Вас, сирота, я оплачу,",0,1520,2,1],["v","Влачить я буду отныне",0,1520,2,0],["v","Свой век в слезах непрестанных.⟩",0,1521,2,0],["v","Пряди волос в тоске",0,1522,3,0],["v","Я себе вырвала.",0,1523,3,0],["v","Где положить мне вас,",0,1524,3,0],["v","Горем венчанные?",0,1525,3,0],["v","Грудь ли кормилицу",0,1525,3,0],["v","Вами закрою я",0,1526,3,0],["v","Или у братьев их",0,1527,3,0],["v","Раны разверстые?",0,1528,3,0],["sd","(К чертогу.)"],["v","Горе мне, горе мне, горе мне!",0,1529,2,0],["v","Покинь, о старый отец, чертоги, покинь!",0,1530,0,1],["v","Выйди, слепой, ко мне, влача свою старость!",0,1530,0,0],["v","Ты, который, на вечную тьму осужден,",0,1531,0,0],["v","Тяжкое бремя горя и лет несешь,",0,1532,0,0],["v","В этих углах пустых, всеми покинутый…",0,1533,0,0],["v","Внемли мне, внемли мне, отец!",0,1534,2,0],["v","Внемли из скитаний унылых,",0,1535,2,0],["v","С подушки ль своей,",0,1536,2,0],["v","Слезами облитой…",0,1537,2,0],["scene","Явление девятнадцатое","s24",7,24],["v","Те же и <span class=\"ch\" data-ch=\"edip\">Эдип</span>.",0,1538,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Зачем ты, дева, призывом мне посох вручила?",0,1539,0,0],["v","Зачем слепые шаги",0,1540,4,1],["v","Из мрачных покоев",0,1540,4,0],["v","На свет вызываешь?",0,1541,4,0],["v","Отрадней слепцу там плакать на ложе холодном,",0,1542,0,0],["v","И нужен ли солнцу седой и колеблемый призрак,",0,1543,0,0],["v","Забытая адом меж смертных унылая тень,",0,1544,0,0],["v","Гость больных сновидений?",0,1545,3,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Отец, печальна злая весть моя:",0,1545,0,0],["v","Их больше нет, они не видят солнца,",0,1546,0,0],["v","Ни сыновей, ни той уж нет, отец,",0,1547,0,0],["v","Которая тебе вручила посох,",0,1548,0,0],["v","Заботами лелеяла тебя…",0,1549,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Увы мне! Увы мне!",0,1550,2,1],["v","Для новых стенаний година настала!",0,1550,0,0],["v","[Три жизни! Три жизни! Три жизни!]",0,1551,0,0],["v","О дочь, скажи мне, три светоча эти",0,1552,0,0],["v","Какая судьба дуновеньем своим погасила?",0,1552,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","О отец, отец!",0,1553,3,0],["v","Не корю тебя, не злорадствую.",0,1554,0,0],["v","С болью слово тебе",0,1554,3,0],["v","Мое сердце отдаст:",0,1555,3,0],["v","Твой зарезал их",0,1556,3,0],["v","Дух проклятия:",0,1556,3,0],["v","И огнем палил,",0,1557,3,0],["v","И в бою томил —",0,1558,3,0],["v","Твой, и твой, и твой…",0,1558,3,0],["v","⟨Увы нам, отец!⟩",0,1559,3,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Горе мне! Горе мне!",0,1560,0,1],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Плачешь, старик?",1,1560,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Дети мои…",0,1561,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Ты плачешь и стонешь,",1,1561,0,0],["v","Но если б ты видел",0,1562,0,0],["v","При свете лучей золотой колесницы",0,1563,0,0],["v","Их жалкие трупы…",0,1564,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","О, ужас проклятий… Детей он убил моих, —",0,1565,0,0],["v","Но мать их несчастную, за что ж ее рок убил?",0,1566,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Она не таила ни слез, ни смятенья,",0,1567,0,0],["v","И, их умоляя, она обнажала",0,1568,0,0],["v","Ту грудь, что когда-то обоих вскормила…",0,1569,0,0],["v","Но было уж поздно… В воротах Электры",0,1570,0,1],["v","На поле цветущем предстали ей дети",0,1571,0,0],["v","В разгаре сраженья, как львы молодые,",0,1572,0,0],["v","В пещере одною вскормленные львицей…",0,1573,0,0],["v","Пред ней под напором мечей они пали;",0,1574,0,0],["v","Упали, и скоро подземного бога",0,1575,0,0],["v","Арей возлияньем их стынущей крови",0,1576,0,0],["v","Почтил, угощая в чертогах поддонных,",0,1577,0,0],["v","А мать из сыновней груди вырывает",0,1578,0,0],["v","Меч молча и падает трупом меж мертвых.",0,1579,0,0],["v","О, сколько несчастья для нашего дома",0,1580,0,1],["v","От солнцевосхода до солнцезаката!..",0,1580,0,0],["sp","Корифей"],["v","Тот день скорбей, о, пусть в грядущем он",0,1581,0,0],["v","Счастливыми вознаградится днями.",0,1582,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Довольно слез… Для мертвых гроб милее,",0,1583,0,0],["v","А ты, Эдип, внемли и повинуйся:",0,1584,0,0],["v","Покойный царь мне царство поручил, —",0,1585,0,0],["v","Фиванский трон — приданое невесте",0,1586,0,0],["v","Гемоновой и дочери твоей…",0,1587,0,0],["v","Ты ж этот край немедленно оставишь:",0,1588,0,0],["v","Движение у <span class=\"ch\" data-ch=\"edip\">Эдипа</span> и <span class=\"ch\" data-ch=\"antigona\">Антигоны</span>.",0,1589,0,0],["v","Тиресия пророческий глагол",0,1590,0,1],["v","В тебе открыл источник всех несчастий",0,1590,0,0],["v","И прожитых и будущих, и нас",0,1591,0,0],["v","Ты долее давить бедой не будешь…",0,1592,0,0],["v","Поверь, Эдип, мне тяжко обижать",0,1593,0,0],["v","Тебя, старик, и ненависти нету",0,1593,0,0],["v","В устах моих. Но демон, демон твой",0,1594,0,0],["v","Пугает нас, суля Кадмее старой",0,1595,0,0],["v","Ряд новых бед. Смирися и уйди…",0,1596,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","О тяжкий рок, рождением несчастным",0,1596,1,0],["v","Отметил ты <span class=\"ch\" data-ch=\"edip\">Эдипа</span>! Аполлон,",0,1597,1,0],["v","Когда еще я не глядел на солнце,",0,1598,1,0],["v","Отцу убийцу в сыне возвестил.",0,1599,1,0],["v","Едва на свет явился я, как Лаий,",0,1600,1,1],["v","Родной отец, велел меня убить,",0,1601,1,0],["v","Врага себе провидя в бессловесном…",0,1602,1,0],["v","И те уста, которые искали",0,1603,1,0],["v","Грудь матери, он отдает зверям…",0,1604,1,0],["v","Меня спасли… О, лучше б гору эту",0,1605,1,0],["v","Тогда жерло подземное пожрало!",0,1606,1,0],["v","Я стал отцеубийцею, я мать",0,1607,1,0],["v","Детей своих праматерию сделал,",0,1608,1,0],["v","Чтоб сыновей иль братьев, наградив",0,1610,1,1],["v","Проклятием, полученным от Лая,",0,1610,1,0],["v","Навек услать в бездонный адский мрак.",0,1611,1,0],["v","Я не безумец… Этот взор померкший",0,1612,1,0],["v","И сыновья убитые мои —",0,1613,1,0],["v","Да разве ж мог устроить это смертный?",0,1614,1,0],["v","Подумаешь о будущем… Слепца",0,1615,1,0],["v","Кто ж поведет?.. Иль мертвая воскреснет",0,1615,1,0],["v","И посох бедному изгнаннику подаст?",0,1616,1,0],["v","Иль сыновья цветущие?.. О, дети!",0,1617,1,0],["v","А силы нет в руках моих, Креонт,",0,1618,1,0],["v","Дрожат мои согнутые колени…",0,1619,1,0],["v","Ведь ты убьешь, ведь ты убил меня!",0,1620,1,1],["sd","(Касается его руки, <span class=\"ch\" data-ch=\"kreont\">Креонт</span> отдергивает ее.)"],["v","О, не страшись… Молить тебя не буду:",0,1620,1,0],["v","Под бременем несчастий я поник,",0,1621,1,0],["v","Но не согнусь обнять твои колени…",0,1622,1,0],["v","И кровь царей во мне еще течет.",0,1623,1,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Колен моих с мольбой не обнимая,",0,1624,0,0],["v","Ты прав, старик: тебе бы все равно",0,1625,0,0],["v","Я не позволил в Фивах оставаться.",0,1625,0,0],["sd","(Слугам.)"],["v","А мертвецов немедля разделить:",0,1626,0,0],["v","Вот этого несите в дом оплакать,",0,1627,0,0],["v","Он был царем… А этот, Полиник,",0,1628,0,0],["v","Врагов привел громить родные стены, —",0,1629,0,0],["v","Так вон его! Ни город, ни страна",0,1630,0,1],["v","Его костей презренных не оплачут.",0,1631,0,0],["v","И гражданам я ныне объявляю:",0,1632,0,0],["v","Рука с землей обрядной иль венцом",0,1633,0,0],["v","Да не коснется тела <span class=\"ch\" data-ch=\"polinik\">Полиника</span>, —",0,1634,0,0],["v","Виновного немедленно казнят…",0,1635,0,0],["sd","(<span class=\"ch\" data-ch=\"antigona\">Антигоне</span>.)"],["v","Ты ж прекрати, царевна, причитанья",0,1636,0,0],["v","Над мертвыми и в терем воротись!",0,1637,0,0],["v","Блестящий брак тебе его отворит.",0,1638,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","О мой отец! Тебя мне больше жаль,",0,1639,0,0],["v","Чем наших мертвых. Я уж и не знаю,",0,1640,0,1],["v","Которое из тяжких зол твоих",0,1641,0,0],["v","Всех тяжелей… Ты — весь одно несчастье.",0,1642,0,0],["sd","(<span class=\"ch\" data-ch=\"kreont\">Креонту</span>.)"],["v","Но ты, Креонт, наш новый властелин,",0,1643,0,0],["v","Ужель тебе для первого указа",0,1644,0,0],["v","Так нужен этот горемычный прах?",0,1645,0,0],["sd","(Указывает на тело <span class=\"ch\" data-ch=\"polinik\">Полиника</span>, от которого не отходит до конца сцены.)"],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Не я решил — то воля <span class=\"ch\" data-ch=\"eteokl\">Этеокла</span>.",0,1646,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Безумному один слепец — слуга.",0,1647,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Как? Пренебречь царя священной волей?",0,1648,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Да, если в ней таится вред и зло.",0,1649,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","И псам его, изменника, не бросить?",0,1650,0,1],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Закон богов ты этим оскорбишь.",0,1650,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Он был наш враг — врагом и остается.",0,1651,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","А искупленье, смерть его, Креонт?",0,1652,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Ни гроба нет ему, ни искупленья.",0,1653,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Но где ж вина покойного? Искал",0,1654,0,0],["v","Законного мой <span class=\"ch\" data-ch=\"polinik\">Полиник</span> несчастный.",0,1655,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","И все-таки не будет погребен!",0,1655,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","показывая свои руки"],["v","Из этих рук, из этих рук — ты понял? —",0,1656,0,0],["v","Он погребенье примет, вам назло…",0,1657,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Готовь же и себе могилу подле…",0,1658,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Друзьям отрадно рядом почивать.",0,1659,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","О дерзкая! А в терем, на запор?",0,1660,0,1],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","схватываясь за носилки <span class=\"ch\" data-ch=\"polinik\">Полиника</span>"],["v","Я не отдам, я не отдам вам брата…",0,1661,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Опомнись… Повеления богов…",0,1662,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Они сказали людям: чтите мертвых.",0,1663,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Но брения не примет <span class=\"ch\" data-ch=\"polinik\">Полиник</span>…",0,1664,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","О, сжалься, царь! Хоть ради <span class=\"ch\" data-ch=\"iokasta\">Иокасты</span>.",0,1665,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Оставь! Ты этого не вымолишь ничем.",0,1666,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Омыть его хоть раны, только раны!",0,1667,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Запрещено, тебе я говорю…",0,1668,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Перевязать их тоже не позволишь?",0,1669,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Ни тени почести ему! Ты поняла?",0,1670,0,1],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","целуя <span class=\"ch\" data-ch=\"polinik\">Полиника</span>"],["v","Любимый мой! Устам моим так сладко",0,1670,0,0],["v","Твой бледный прах, лаская, целовать.",0,1671,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["dir","удерживая ее"],["v","Невеста ты, и слезы неприличны,",0,1672,0,0],["v","Несчастный брак они тебе сулят.",0,1673,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Иль ты венчать со мною хочешь сына?",0,1674,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Конечно, да: вы ведь обручены.",0,1675,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Так знай… ему я буду Данаидой.",0,1675,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["dir","в ужасе отступает"],["v","Как дерзки вы, о нежные уста…",0,1676,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","указывая на окровавленный меч, лежащий около <span class=\"ch\" data-ch=\"polinik\">Полиника</span>"],["v","Мечом клянусь и смертию железной!<a class=\"nr\" href=\"#n-k63\" data-n=\"k63\" aria-label=\"Примечание 63\">63</a>",0,1677,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Но почему ж от брака ты бежишь?",0,1678,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","С отцом делить хочу его изгнанье.",0,1679,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Великодушие, но детское, прости…",0,1680,0,1],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Я даже смерть с ним разделить готова.",0,1680,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Так уходи ж, а сына я не дам",0,1681,0,0],["v","Тебе убить. Оставь немедля Фивы!",0,1682,0,0],["sd","(<span class=\"ch\" data-ch=\"kreont\">Креонт</span> уходит.)"],["scene","Явление двадцатое","s25",7,25],["v","<span class=\"ch\" data-ch=\"edip\">Эдип</span> и <span class=\"ch\" data-ch=\"antigona\">Антигона</span>.",0,1682,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Твоя любовь, желание твое",0,1683,0,0],["v","Мне дороги, но… оставайся в Фивах…",0,1684,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","И выйди замуж, да? Отец, а ты?",0,1685,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Полюбим мы: ты — мужа, я — страданья.",0,1685,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","А кто ж тебя, слепого, сбережет?",0,1686,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Пойду, пока судьба и ноги носят.",0,1687,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Эдип, Эдип! Где слава мудреца?",0,1687,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Да, мой венец плели недолго боги,",0,1688,0,0],["v","И в миг один потом он облетел…",0,1689,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Кому ж делить теперь твои страданья?",0,1690,0,1],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Подумай, дочь: слепец и нищета…",0,1690,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","О, чистая изгнанья не страшится,",0,1691,0,0],["v","И жертвовать отрадно ей, отец.",0,1692,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["dir","направляясь к трупам"],["v","Где мать лежит? Любимого лица",0,1693,0,0],["v","Коснуться дай рукой дрожащей старцу.",0,1694,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","берет его руку и приближает ее к лицу <span class=\"ch\" data-ch=\"iokasta\">Иокасты</span>"],["v","Ты щек ее касаешься, старик.",0,1695,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["dir","припадает к ней"],["v","О, мать моя! О, бедная подруга!",0,1695,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Испившая всю горечь наших зол…",0,1696,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","А <span class=\"ch\" data-ch=\"eteokl\">Этеокл</span>? А <span class=\"ch\" data-ch=\"polinik\">Полиник</span>? О, дети!",0,1697,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","перемещая его руки на сыновей"],["v","Они лежат перед тобой, отец…",0,1698,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Моя рука нащупать лиц не может.",0,1699,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","кладет его руки на лица <span class=\"ch\" data-ch=\"eteokl\">Этеокла</span> и <span class=\"ch\" data-ch=\"polinik\">Полиника</span>"],["v","Дай мне ее… Ты гладишь их теперь.",0,1700,0,1],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","О, милый прах, о, дети несчастливца!",0,1700,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","О Полиник! Как сладок этот звук!",0,1701,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Пророчество… Ты наконец свершилось…",0,1702,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Пророчество… Иль новая беда?..",0,1702,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Мне Феб вещал, что я умру в Афинах.",0,1703,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","И в Аттике наметил ты приют?",0,1704,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","В божественном Колоне Посейдону",0,1705,0,0],["v","Алтарь и храм воздвигли в старину.",0,1705,0,0],["v","Там я умру. Но если, Антигона,",0,1706,0,0],["v","В душе твоей желание горит",0,1707,0,0],["v","С изгнанником делить его невзгоды,",0,1707,0,0],["v","Нас больше здесь не держит ничего.",0,1708,0,0],["v","<span class=\"ch\" data-ch=\"antigona\">Антигона</span> прилаживается вести <span class=\"ch\" data-ch=\"edip\">Эдипа</span>.",0,1709,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Дай руку, отец!",0,1710,0,1],["v","Я буду — как ветер летучий,",0,1711,0,0],["v","А ты — как тяжкий корабль.",0,1712,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Ты веди меня, дитятко,",0,1713,0,0],["v","Горемычного горемычная.",0,1714,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","О, есть ли меж вами,",0,1715,0,0],["v","Подруги мои,",0,1716,0,0],["v","Несчастнее кто <span class=\"ch\" data-ch=\"antigona\">Антигоны</span>?..",0,1717,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Я дрожащей ногой и тропы не найду,",0,1718,0,0],["v","Дай мне посох, дитя.",0,1719,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["dir","наклоняется и подает ему посох"],["v","Твоею ногою и ветер играет,",0,1720,0,1],["v","Вот так, полегоньку!",0,1720,0,0],["v","Потише, потише…",0,1721,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","О, новый и тягостный мрак!",0,1722,0,0],["v","О, тьма нищеты и изгнанья!",0,1723,0,0],["v","За что изгоняют?..",0,1724,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","За что, злополучный?",0,1725,0,0],["v","Как будто не знаешь,",0,1725,0,0],["v","Что гордо на свете",0,1726,0,0],["v","Насилье ликует,",0,1727,0,0],["v","А правда убита, а правда убита?",0,1728,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Это тот человек, что победой богов",0,1729,0,0],["v","Увенчался, их тайну похитив?..",0,1730,0,1],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Зачем вспоминаешь ты прошлую славу, родимый,",0,1731,0,0],["v","Когда от победы над девой крылатой одно лишь",0,1732,0,0],["v","Наследье тебе остается: изгнанье и смерть под забором?",0,1733,0,0],["v","А мне — сожаленья и слезы разлуки.",0,1734,0,0],["v","И после неги чертога весь ужас скитанья…",0,1735,0,0],["v","О боги! Пошлите же мне,",0,1736,3,0],["v","На счастье <span class=\"ch\" data-ch=\"edip\">Эдипу</span>,",0,1737,3,0],["v","И разум и доблесть.",0,1740,3,1],["sd","(Идет и затем останавливается.)"],["v","О нет… Неужели",0,1741,3,0],["v","Я брошу его",0,1742,4,0],["v","И он погребенья и ласки последней лишится?",0,1743,1,0],["v","Отец мой, отец мой,",0,1744,3,0],["v","Уйти я не в силах…",0,1745,3,0],["v","Пока я землею его не засыплю.",0,1746,2,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["dir","оставляя ее руку"],["v","К подругам вернись.",0,1747,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Им слезы мои что скажут, отец?",0,1748,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","Иди к алтарям и молись.",0,1749,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Им горе мое наскучило, старец.",0,1750,0,1],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","А туда, моя дочь,",0,1750,0,0],["v","В белоснежную высь,",0,1751,0,0],["v","В хоровод Диониса?",0,1752,0,0],["sp","<span class=\"ch\" data-ch=\"antigona\">Антигона</span>"],["v","Нет, туда не пойду.",0,1753,0,0],["v","Я носила, отец,",0,1753,0,0],["v","Лани пестрой покров.",0,1754,0,0],["v","В хороводе его",0,1755,0,0],["v","Ударяла в тимпан —",0,1756,0,0],["v","И в изгнанье иду…",0,1756,0,0],["v","Сердца нет у богов.",0,1757,0,0],["sp","<span class=\"ch\" data-ch=\"edip\">Эдип</span>"],["v","О сыны моей отчизны… Поглядите на <span class=\"ch\" data-ch=\"edip\">Эдипа</span>!",0,1758,0,0],["v","Разгадал он тайну девы и не знал пределов славы",0,1759,0,0],["v","В день, когда плененный город от убийцы он избавил,",0,1760,0,1],["v","В обесчещенном и дряхлом узнаете ль вы <span class=\"ch\" data-ch=\"edip\">Эдипа</span>?",0,1761,0,0],["v","Но зачем все эти стоны? Много горя в этом мире,",0,1762,0,0],["v","Если так решили боги, прах ничтожный, покоряйся!..",0,1763,0,0],["sd","(Берет посох и направляется к выходу.)"],["v","За ним медленно идет <span class=\"ch\" data-ch=\"antigona\">Антигона</span>.",0,1764,0,0],["sp","Хор"],["v","Благовонной короной своей",0,1765,0,0],["v","Увенчай поэта, победа,<a class=\"nr\" href=\"#n-k64\" data-n=\"k64\" aria-label=\"Примечание 64\">64</a>",0,1766,0,0],["v","И не раз, и не два, и не три",0,1767,0,0],["v","Ты увей его белые кудри!",0,1768,0,0],["sd","(Покидает сцену.)"],["h1","Комментарий","comm"],["p","Трагедия поставлена в период между 411 и 409 гг. до н.э.; вместе с несохранившимися «Эномаем» и «Хрисиппом» она заняла второе место."],["p","Лежащий в основе трагедии миф о вражде сыновей Эдипа был до Еврипида обработан в фиванской трилогии Эсхила (467 г.), от которой дошла только ее заключительная часть «Семеро против Фив», а также отчасти в «Антигоне» Софокла (ок. 442 г.). Об отличии Еврипида от своих предшественников в трактовке образа Этеокла см. вступительную статью, с. 571. Здесь необходимо только вкратце остановиться на генеалогии фиванских царей, поскольку эта тема часто затрагивается в трагедии (ст. 5 — 13, 638 — 682, 818 — 832), и на взаимоотношении Эдипа с сыновьями после того, как стали ясны совершенные им по неведению преступления."],["p","Фиванцы возводили родословную своих героев к аргосской царевне Ио, которая от союза с Зевсом родила Эпафа; его дочь — Ливия родила от брака с Посейдоном двух близнецов — Бела и Агенора; первому достался царский трон в Египте, второму в Финикии (в Тире или Сидоне). Когда дочь Агенора, красавица Европа, была похищена Зевсом, он разослал на розыски сестры своих сыновей, и среди них — Кадма. Добравшись до Эллады и не найдя Европы, Кадм, вопросив Дельфийский оракул о своем будущем, получил указание следовать за коровой, которая ему повстречается на пути, и там, где она, устав, ляжет отдыхать, основать город. Корова привела Кадма на то место, где затем были основаны Фивы. Здесь Кадму пришлось вступить в битву с драконом Ареса, охранявшим местный источник: зубами убитого дракона Кадм, по совету Афины, засеял близлежащий участок земли, из которой тотчас выросли вооруженные воины, начавшие избивать друг друга в ожесточенной схватке. От пяти уцелевших «спартов» (т. е. «посеянных») вела впоследствии свою родословную фиванская знать. Что касается Кадма, то Apec со временем простил ему убийство дракона и выдал за него свою дочь Гармонию, рожденную ему Афродитой; пышную свадьбу Кадма и Гармонии почтили своим присутствием сами боги. По имени Кадма получила название Кадмея — фиванский акрополь. Внуком Кадма был Лабдак, правнуком — Лаий, от брака которого с Иокастой родился Эдип. В свою очередь, Иокаста и ее брат Креонт, дети Менекея, возводили свое происхождение к дочери Кадма Агаве, выданной замуж за одного из «спартов», Эхиона. Таким образом, все участники драмы, разыгравшейся в Фивах после гибели Лаия, связаны с их общим предком, финикийцем Кадмом, что дает основание хору трагедии, введенному Еврипидом по достаточно случайному поводу, в какойто мере обосновать свою заинтересованность в происходящем (см. ст. 243 — 249, 291 сл.)."],["p","История рождения Эдипа и его дальнейшая судьба излагается в «Финикиянках» (ст. 13 — 62, 379 — 381, 801 — 817, 1043 — 1050, 1589 — 1611) в общем в согласии с традиционной версией, обработанной Софоклом («Царь Эдип»); отступление представляют только ст. 47 — 49, 1204 — 1206, из которых следует, что рука Иокасты была уже заранее обещана Креонтом тому, кто избавит город от Сфинкса, в то время как у Софокла Эдип стал мужем Иокасты только в силу стечения обстоятельств."],["p","О взаимоотношениях Эдипа с его сыновьями повествовала послегомеровская эпическая поэма «Фиваида», из которой сохранилось несколько небольших отрывков. Суть дела сводилась к тому, что, хотя ослепивший себя Эдип продолжал жить в своем дворце в Фивах, Этеокл и Полиник запретили ему появляться на людях, надеясь таким образом погасить мрачную молву о своем происхождении (ср. ст. 63 — 65). Постепенно они стали относиться к отцу со все меньшим почтением: один раз они послали ему неподобающую часть мяса от жертвенного животного, в другой раз подали кубок убитого им самим Лаия. Эдип увидел в этом оскорбительное напоминание о его прошлом и в гневе проклял сыновей, завещав им делить мечом отцовское наследство. В такой, наиболее естественной, последовательности эти события излагаются в «Финикиянках» в ст. 872 — 877. Наряду с этим, однако, уже в «Семерых…» Эсхила можно наблюдать известное смещение хронологической перспективы, находящее отражение и у Еврипида, в ст. 66 — 68, 253 — 255, 474 — 479, из которых возникает представление, будто Эдип проклял сыновей без всякого повода с их стороны. Логическая связь между событиями, конечно, этим нарушается, но зато сгущается трагическая атмосфера, окутывающая образы Иокасты и обоих братьев."],["p","Уже древние критики ставили в вину Еврипиду «переполнение» «Финикиянок» побочными эпизодами, не имеющими прямого отношения к основному конфликту; к числу таких сцен, несомненно, относится обозрение вражеского войска с крыши Фиванского дворца (ст. 88 — 192), мотив жертвоприношения Менекея (ст. 889 — 1018), спор Антигоны с Креонтом о погребении Полиника (ст. 1643 — 1671), и в новое время не раз делались попытки заподозрить в подлинности тот или иной эпизод «Финикиянок». Подобные стремления нельзя признать всегда основательными. Прежде всего по самому замыслу «Финикиянки», наряду с «Троянками», принадлежат к типу трагедий, которые уже Аристотель называл «эпизодическими», вполне допуская существование такой жанровой разновидности. А затем некоторые сцены, на первый взгляд кажущиеся лишними, играют существенную роль в замысле целого; так, индивидуализм и антиобщественное поведение обоих братьев выявляются еще отчетливее при сравнении с патриотическим самопожертвованием Менекея."],["p","Анненский напечатал свой перевод «Финикиянок» в журнале, рассчитанном на широкого читателя («Мир Божий, 1898, Э 4), и не успел переработать его для переиздания. Отсюда некоторая избыточность в ремарках. Самый смелый домысел в них — »закат солнца« в начале и ночной »мрак« при появлении Полиника — опирается только на молитву к Артемиде-Луне (ст. 176) и на неправильно понятые слова Полиника (ст. 276: в подлиннике — »темные ножны«). Вряд ли »смотр со стены\" Антигоны и старика можно себе представить в вечерних сумерках."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"],["note","k35"],["note","k36"],["note","k37"],["note","k38"],["note","k39"],["note","k40"],["note","k41"],["note","k42"],["note","k43"],["note","k44"],["note","k45"],["note","k46"],["note","k47"],["note","k48"],["note","k49"],["note","k50"],["note","k51"],["note","k52"],["note","k53"],["note","k54"],["note","k55"],["note","k56"],["note","k57"],["note","k58"],["note","k59"],["note","k60"],["note","k61"],["note","k62"],["note","k63"],["note","k64"]],"n":{"k1":["Ст. 1 — 87","В отличие от традиционной версии, зафиксированной уже в «Одиссее», XI, 271 — 280, еврипидовская Иокаста осталась жить после разоблачения тайны ее преступного брака."],"k2":["Ст. 1 — 2","в оригинале — как видно из недавней папирусной находки, позднее добавление."],"k3":["Ст. 27. …Стопы ему пронзив…","Стих объясняет происхождение имени «Эдип», что значит по-гречески: «с опухшими ногами»."],"k4":["Ст. 44. …Поливу ее отвез…","Возвращение Эдипа к Полибу — деталь, известная только из более поздних источников."],"k5":["Ст. 77 — 79. …Отправился в Микены… собрав аргосские дружины…","Трагедия V в. обычно не делает различия между Аргосом и Микенами."],"k6":["Ст. 101 сл. Исмен","река вблизи Фив."],"k7":["Ст. 123. Начальник, госпожа.","В оригинале он назван лохагом (см. ст. 749), т. е. командиром отряда."],"k8":["Ст. 123 — 189","Хотя в другом месте (ст. 751 сл.) Еврипид полемически отвергает описание семи фиванских полководцев, широко разработанное у Эсхила в «Семерых…», в изображении нападающих на Фивы аргосцев он достаточно близко следует за своим предшественником, смягчая только их резко отрицательную характеристику, данную Эсхилом: в годы постановки «Финикиянок» Аргос был союзником Афин."],"k9":["Ст. 126. Лерна","город на берегу Арголидского залива."],"k10":["Ст. 129. Стероп","имя не гиганта, а одного из киклопов; но здесь просто в этимологическом значении «звездоподобный»."],"k11":["Ст. 134. …панцирь… зтолийский…","Этолия — область в западной части Средней Греции."],"k12":["Ст. 136. …Женаты на сестрах родных…","См. ниже, ст. 411 — 430. Тидей должен был покинуть родину после убийства одного из своих родственников."],"k13":["Ст. 150. Аталанта","персонаж из аркадского круга мифов. Подброшенная отцом на горе Парфенион, она была вскормлена медведицей и выросла среди охотников. Длительное время избегая замужества, она в конце концов родила от этолийского героя Мелеагра (или самого бога Ареса) сына Парфенопея."],"k14":["Ст. 155","Неудачный перевод; точнее:<br>«Боюсь, и боги помогают им»."],"k15":["Ст. 160. …около могилы… Ниобид…","Трагедия Ниобы, потерявшей в один день семерых сыновей и столько же дочерей (Ниобид), разыгралась на Фиванской равнине, так как мужем Ниобы, по одной из версий, был Амфион."],"k16":["Ст. 173. Амфиарай","знаменитый прорицатель, женатый, как Полиник и Тидей, на одной из дочерей Адраста."],"k17":["Ст. 176. Артемида моя Златолунная!","Артемиду часто отождествляли с Селеной, богиней луны; так она и названа в оригинале."],"k18":["Ст. 179 — 189. …царь Капаней, с его угрозой дерзкой?","Бессознательная реминисценция из Эсхила: в «Семерых…» Капаней грозится сжечь Фивы, независимо от того, угодно это или нет Зевсу (ст. 425 — 434). Антигона, впервые видящая аргосские войска, еще не может этого знать. Дева отмщения — Немесида, олицетворение возмездия. Лерне… рабынь насулил… — Близ Лерны (см. ст. 126) находился источник, посвященный Посейдону; носить воду составляло обычную обязанность пленниц {ср. «Илиада», VI, 457)."],"k19":["Ст. 202 сл","Присутствие финикийских девушек объясняется тем, что по дороге из Тира в Дельфы они вынуждены были задержаться в Фивах из-за разгоревшейся войны."],"k20":["Ст. 205. …И горькой я стала рабыней.","Здесь и далее — преувеличение переводчика. Девушки, отобранные для служения Аполлону в его Дельфийском храме, конечно, лишались радостей «мирской» жизни, но их «священное рабство» в качестве храмовых прислужниц считалось почетной привилегией."],"k21":["Ст. 211. Сицилии влажные нивы.","Каким образом могли девушки из Тира, с побережья Малой Азии, попасть в Сицилию по дороге в Грецию? Некоторые исследователи объясняют это тем, что под финикиянками Еврипид разумеет девушек из Карфагена (основанного финикийцами в IX в. до н. э.), и тогда их маршрут вполне разумен. Намек же на Карфаген понадобился Еврипиду для того, чтобы напомнить афинянам о победе, одержанной карфагенянами в 409 г. над сицилийцами, — в Афинах, несомненно, рады были узнать о поражении их недавних противников. Однако в тексте трагедии эта гипотеза не находит другого подтверждения и нуждается в более основательных доказательствах."],"k22":["Ст. 232. Дракона божественный грот.","Здесь речь идет о чудовище Пифоне (см. примеч. к «Ифигении в Тавриде», ст. 1234 — 1283). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ифигения в Тавриде», Ст. 1234-1283.</b> «Дифирамбический стасим» (см. примеч. к «Гекубе», ст. 905-952), почти не связанный с содержанием трагедии. Речь идет об учреждении дельфийского прорицалища Аполлона. Первоначально здесь находился оракул Фемиды, охраняемый драконом Пифоном: убив дракона, Аполлон завладел прорицалищем. Несколько иначе этот миф излагается в так называемом гомеровском гимне к Аполлону Пифийскому (ст. 171-196) и в «Евменидах» Эсхила, ст. 1-20. В антистрофе (1259 сл.) используется, по-видимому, какая-то храмовая легенда о соперничестве Аполлона с бывшей владелицей прорицалища.</span><!--/xn-->"],"k23":["Ст. 237. Пред жерлом священным","перед входом в храм Аполлона или перед расселиной, над которой устанавливался треножник прорицательницы Пифии."],"k24":["Ст. 255. …Эриний рукой вражда зажжена?","Здесь Эринии выступают как исполнительницы проклятия, призванного Эдипом на головы своих сыновей."],"k25":["Ст. 260. Точила вечная правда.","Несколько усиленная переводчиком мысль оригинала, что Полиник имеет право вернуть себе силой отобранную у него часть отцовского наследства (ср. ст. 154 сл., 491 — 493,547 — 551). В этой части характеристика Полиника у Еврипида особенно резко расходится с эсхиловской, где для. Полиника нет никакого оправдания (см. «Семеро против Фив», ст. 580 — 583:<br>Ужель богам любезен этот подвиг твой,<br>Иль у потомков хочешь ты прославиться,<br>Разрушив отчий город и родных богов<br>Во власть отдавши войску чужеземному?)."],"k26":["Ст. 294. Свой я закон храню…","Простираться ниц перед царями греки считали обычаем «варваров», а не свободных эллинов."],"k27":["Ст. 331 сл. …Зарезаться он порывался…","Деталь, совершенно не известная из других источников."],"k28":["Ст. 368. Гимнасий","место для физических упражнений."],"k29":["Ст. 391. Речей… свободных он лишен.","Деталь из афинской жизни V в.: неотъемлемым правом гражданина считалась свобода слова."],"k30":["Ст. 409. Оракул был от Локсия царю","Адрасту. Локсий — культовое имя Аполлона."],"k31":["Ст. 449. Повзводно","модернизм переводчика: Этеокл расставляет в боевом порядке отряды фиванских воинов."],"k32":["Ст. 469 — 525","В оригинале речи Полиника и Этеокла точно равны по объему — еще один пример тщательно обработанного агона (см. примеч. к «Гекубе», ст. 1132 — 1182, 1187-1237). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Гекуба», Ст. 1132-1182.</b> , 1187-1237 — очередной пример ораторского агона (см. примеч. к «Медее», ст. 465-575), составленного из двух равных по объему речей. Полиместор завершает свою речь «общим местом», Гекуба, напротив, начинает свой монолог с такого же рассуждения на общую тему.</span><!--/xn-->"],"k33":["Ст. 561 — 567",",571 — 577. Иокаста адресует обоим братьям упреки, которые в «Семерых…» Эсхила, ст. 580 — 586, обращены только к Полинику."],"k34":["Ст. 588 — 637","Диалог в трохеических тетраметрах, которые переводчик снабжает чуждой оригиналу рифмой. Ср. «Ифигения в Тавриде», ст. 1202 — 1221. Ст. 606. Стены братьев белоконных — Амфиона и Зета."],"k35":["Ст. 614","Перевод весьма приблизительный. В оригинале на слова Полиника («Не беспокойся, я ухожу! Прощай, мать!») Этеокл отвечает только: «Уходи из города!»"],"k36":["Ст. 636 сл. …недаром был ты назван Полиником…","Имя «Полиник» разлагается по-гречески на две составные части: poly — «много» и neikos — «вражда», «брань» (см. также ст. 1494 сл.)."],"k37":["Ст. 640. Поля Аонийские","название Беотии по имени ее древнейшего населения — аонийцев."],"k38":["Ст. 650 сл. …плюща зеленые кудри…","По одной легенде, когда дворец Кадма загорелся от перунов Зевса, из-под земли пробился плющ, чтобы оградить от опасности младенца Диониса. Плющ являлся непременным атрибутом культа Диониса на протяжении всей античности. Эвий — культовое наименование Диониса."],"k39":["Ст. 685. …соименных богинь…","В оригинале: «двуименных богинь» — не вполне ясный эпитет; может быть, это просто поэтический эквивалент числительного «две»."],"k40":["Ст. 690. Сына Менекея","Креонта (см. вступит, заметку)."],"k41":["Ст. 733. Колесами их лагерь обнесен.","Неясный перевод. Смысл оригинала: «Но и их войско защищено стеной колесниц», т. е. и у аргосцев есть хорошая конница, способная отразить кавалерийский набег."],"k42":["Ст. 739","Перевод произвольный. Точнее:<br>«Вести врагов на штурм семи ворот»."],"k43":["Ст. 759 сл. С сестрой моей его я сговорил…","Так как слепой Эдип не идет в счет, право распоряжаться судьбой сестры получает в соответствии с афинскими законами ее брат."],"k44":["Ст. 774 — 777. Последний мой приказ…","Сознательное изменение мифа по сравнению с традиционным вариантом, принятым у Софокла: там Креонт отдал распоряжение бросить тело Полиника без погребения."],"k45":["Ст. 793. Бромий","культовое имя Диониса."],"k46":["Ст. 805. …С пронизанной златом пяткой?","Младенцу Эдипу, прежде чем бросить его в горах, прокололи золотой булавкой сухожилия у лодыжки (см. ст. 26 сл.)."],"k47":["Ст. 806. Крылатая дева","Сфинкс."],"k48":["Ст. 822. Первую славу отчизне.","В подлиннике о земнородных спартах сказано двусмысленнее: «прекраснейший позор Фивам»."],"k49":["Ст. 838 — 840. …записи гаданий…","Речь идет, конечно, не о каких-либо прочитанных Тиресием священных текстах, а о записи предзнаменований, которые он извлек из полета и криков птиц (см. примеч. к «Ипполиту», ст. 1058). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ипполит», Ст. 1058.</b> …птицы, в небесах… — По полету птиц специальные гадатели определяли будущее и угодность богам того или иного решения смертных.</span><!--/xn-->"],"k50":["Ст. 854 — 857. …С царем фракийским…","Ошибка Анненского. Имеется в виду Евмолп, элевсинский царь. Согласно древнему аттическому преданию, он пошел войной на афинян (Кекропидов — по имени их первого царя), но потерпел поражение, а сын его был убит афинским царем Эрехтеем; последний, чтобы одержать победу, должен был принести в жертву собственную дочь. Это предание Еврипид использовал в несохранившейся трагедии «Эрехтей»."],"k51":["Ст. 931 — 952","Так как хор совсем недавно пел о свадьбе Кадма с Гармонией, то ясно, что Apec давно примирился с его родом, и мотив искупления человеческой кровью крови убитого дракона привлечен здесь Еврипидом только для того, чтобы обосновать жертвоприношение Менекея. Возможно, и весь этот эпизод — нововведение Еврипида."],"k52":["Ст. 983. Феспрот","область в Эпире (северо-западная Греция), где находился додонский храм Зевса, покровителя молящих о защите. Естественно, что Креонт стремится укрыть сына в далеком от Фив святилище Зевса, а не в близлежащем дельфийском храме Аполлона, который сам являлся покровителем прорицателей."],"k53":["Ст. 988 сл. Без матери остался я…","Этими стихами отклоняется вариант мифа, принятый Софоклом в «Антигоне», где жена Креонта кончает жизнь самоубийством, узнав о смерти своего единственного сына Гемона."],"k54":["Ст. 1019 — 1042","По Гесиоду («Теогония», ст. 298 сл., 326 сл.), Сфинкс родилась от брака чудовищной Ехидны (полуженщины, полузмеи) и не менее чудовищного Тифона. Следует обратить внимание, что здесь, как и в ст. 806 — 810, Сфинкс изображена как женское чудовище, прилетающее время от времени в Фивы и уносящее в своих когтях очередную жертву, в то время как более традиционное представление рисует ее сидящей на скале по дороге в Фивы в ожидании проходящего мимо нее путника."],"k55":["Ст. 1104 — 1140","Еврипид дает достаточно подробную диспозицию нападающих, называя шесть из семи фиванских ворот: Неитские (на восточной стороне), Претовы (на северо-востоке), Крены (т. е. у Источника, — на севере), Огигии (в переводе: «Старые», — на юге), Электрины (на юго-востоке) и Гомоловы (местонахождение неизвестно, может быть, на юго-западной стороне)."],"k56":["Ст. 1124. Потнийскими конями Ныл украшен","легендарные кони царя Главка из беотийского города Погний; Главк кормил своих коней человеческим мясом."],"k57":["Ст. 1147. Гимнеты","легковооруженные воины."],"k58":["Ст. 1162. Менала дочь","Аталанта (см. примеч. к ст. 150). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>Ст. 150. Аталанта.</b> персонаж из аркадского круга мифов. Подброшенная отцом на горе Парфенион, она была вскормлена медведицей и выросла среди охотников. Длительное время избегая замужества, она в конце концов родила от этолийского героя Мелеагра (или самого бога Ареса) сына Парфенопея.</span><!--/xn-->"],"k59":["Ст. 1335 — 1339. В оригинале","трохеические тетраметры, которыми Анненский переводит только два средних стиха."],"k60":["Ст. 1365. Ты помоги мне, Гера…","Полиник обращается к Гере как наиболее почитаемой богине аргосцев (см. примеч. к «Электре», ст. 171 — 174). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Электра», Ст. 171 — 174. …к… Гере в Аргосский храм девы сбираются….</b> Речь идет о большом празднестве в честь Геры, покровительницы Аргоса (см. Геродот, I, 31), которое справлялось в священном округе Гереоне, примерно в восьми километрах от Аргоса.</span><!--/xn-->"],"k61":["Ст. 1480 — 1484. В оригинале","анапестические диметры."],"k62":["Ст. 1485. Я румяных щек не таила…","Потрясенная горем Антигона не соблюдает обычая, предписывающего девушке выходить на люди с лицом, закрытым фатой."],"k63":["Ст. 1677","Данаидой, т. е. мужеубийцей: пятьдесят сестер-данаид, насильно выданных за своих двоюродных братьев, умертвили их в брачную ночь; только одна пожалела мужа, и от них пошел род аргосских царей (ассоциация с сюжетом «Финикиянок»)."],"k64":["Ст. 1737 — 1766","большинство исследователей считают неподлинными."]},"mainEnd":2796,"c":[{"id":"iokasta","name":"Иокаста","role":"Мать и жена Эдипа","intro":"Царица, которая пережила разоблачение Эдипа и теперь пытается примирить сыновей.","arc":"В отличие от Софокла, у Еврипида Иокаста не покончила с собой: она живёт в Фивах, состарившаяся, в трауре, и прологом пересказывает всю историю дома Лабдакидов. Она добивается перемирия и сводит сыновей лицом к лицу; её речь о Равенстве против Честолюбия — призыв к разуму, который никто не слышит. Когда поединок становится неизбежным, она бежит с Антигоной на поле и умирает над телами сыновей, заколовшись их мечом.","st":[{"i":133,"p":5,"l":"Пролог · явление первое","t":"Пролог","d":"Рассказывает о Лаии, Эдипе, проклятии сыновей и о том, что Полиник привёл к Фивам аргосское войско.","c":"Последняя надежда — свидание братьев.","k":false},{"i":725,"p":26,"l":"Действие первое · явление четвертое","t":"Встреча с изгнанником","d":"Обнимает Полиника после долгой разлуки, расспрашивает о жизни на чужбине.","c":"","k":false},{"i":1043,"p":37,"l":"Действие первое · явление пятое","t":"Посредничество","d":"Убеждает Этеокла отказаться от Честолюбия, «худшей из богинь», и почтить Равенство; Полинику напоминает, что, взяв Фивы, он разорит родной город.","c":"Разум против властолюбия — и поражение разума.","k":true},{"i":2061,"p":74,"l":"Действие четвертое · явление пятнадцатое","t":"На поле битвы","d":"Узнав о поединке, зовёт Антигону, и они бегут к войску, чтобы встать между братьями.","c":"","k":false},{"i":2333,"p":83,"l":"Действие пятое · явление семнадцатое","t":"Смерть над сыновьями","d":"Вестник рассказывает: она застала сыновей умирающими и заколола себя над ними.","c":"","k":false}],"gen":"Иокаста"},{"id":"polinik","name":"Полиник","role":"Младший сын Эдипа","intro":"Изгнанник, который привёл аргосское войско против родного города.","arc":"Полиник по-своему прав: брат нарушил уговор царствовать поочерёдно. Он тоскует по родине и боится ловушки в городе, куда пришёл под охраной перемирия. Умирая, он просит мать и сестру похоронить его в родной земле.","st":[{"i":489,"p":17,"l":"Действие первое · явление третье","t":"Тайно в Фивах","d":"С мечом в руке входит в город по зову матери, вздрагивая от каждого шороха.","c":"","k":false},{"i":1043,"p":37,"l":"Действие первое · явление пятое","t":"Требование справедливости","d":"Излагает своё право на очередь в царстве.","c":"","k":false},{"i":1063,"p":38,"l":"Действие первое · явление шестое","t":"Разрыв","d":"Обменивается с братом угрозами: встретятся на поле у ворот.","c":"Примирение невозможно.","k":true},{"i":2333,"p":83,"l":"Действие пятое · явление семнадцатое","t":"Гибель","d":"В поединке смертельно ранит брата и сам погибает; умирая, просит о погребении в Фивах.","c":"","k":false}],"gen":"Полиник"},{"id":"eteokl","name":"Этеокл","role":"Старший сын Эдипа, царь Фив","intro":"Царь, открыто ставящий власть выше справедливости.","arc":"Этеокл откровенен до цинизма: «Если уж преступать закон, то ради власти». Он не желает уступать ни на шаг и готовит город к обороне, а Креонту поручает после его смерти не хоронить Полиника.","st":[{"i":1043,"p":37,"l":"Действие первое · явление пятое","t":"Отказ уступить","d":"Признаёт, что ради царской власти пойдёт на любое преступление.","c":"Власть дороже брата.","k":true},{"i":1297,"p":46,"l":"Действие второе · явление восьмое","t":"Совет с Креонтом","d":"Распределяет вождей по воротам, просит Креонта женить Гемона на Антигоне и запретить погребение Полиника.","c":"","k":false},{"i":2333,"p":83,"l":"Действие пятое · явление семнадцатое","t":"Гибель","d":"Умирает в поединке с братом.","c":"","k":false}],"gen":"Этеокл"},{"id":"kreont","name":"Креонт","role":"Брат Иокасты","intro":"Правитель, у которого боги требуют сына.","arc":"Креонт — отец прежде, чем правитель: услышав от Тиресия, что для спасения Фив должен умереть его сын, он отказывается и велит Менекею бежать. После гибели всего царского рода он становится царём и исполняет суровую волю Этеокла.","st":[{"i":1597,"p":57,"l":"Действие третье · явление девятое","t":"Пророчество","d":"Тиресий объявляет: Фивы спасёт только смерть Менекея, последнего чистого потомка спартов.","c":"","k":false},{"i":1658,"p":59,"l":"Действие третье · явление десятое","t":"Отказ от жертвы","d":"Готов умереть сам, но не отдать сына; велит ему бежать из города.","c":"Любовь к сыну сильнее долга перед городом.","k":true},{"i":2135,"p":76,"l":"Действие пятое · явление шестнадцатое","t":"Тело сына","d":"Приносит тело Менекея и ищет Иокасту, чтобы обмыть его.","c":"","k":false},{"i":2644,"p":95,"l":"Исход · явление девятнадцатое","t":"Новый царь","d":"Изгоняет Эдипа, запрещает хоронить Полиника и требует, чтобы Антигона стала женой Гемона.","c":"","k":false}],"gen":"Креонт"},{"id":"menekey","name":"Менекей","role":"Сын Креонта","intro":"Юноша, который обманывает отца, чтобы умереть за город.","arc":"Менекей притворно соглашается бежать, а оставшись один, объявляет хору, что отдаст жизнь за Фивы: было бы позором бежать, когда другие сражаются.","st":[{"i":1694,"p":61,"l":"Действие третье · явление одиннадцатое","t":"Добровольная смерть","d":"Объявляет, что бросится со стены в логово дракона, чтобы спасти город.","c":"Ещё одна добровольная жертва Еврипида.","k":true}],"gen":"Менекей"},{"id":"antigona","name":"Антигона","role":"Дочь Эдипа","intro":"Царевна, которая из робкой девочки становится защитницей рода.","arc":"В начале Антигона — затворница, которую старик выводит на кровлю посмотреть на вражеское войско. В конце она открыто бросает вызов Креонту: отказывается от брака, обещает похоронить Полиника и уводит слепого отца в изгнание.","st":[{"i":331,"p":12,"l":"Пролог · явление второе","t":"На кровле","d":"Со стариком-рабом смотрит на аргосских вождей и ищет среди них брата.","c":"","k":false},{"i":2061,"p":74,"l":"Действие четвертое · явление пятнадцатое","t":"Зов матери","d":"Иокаста выводит её из дома и ведёт на поле битвы.","c":"","k":false},{"i":2413,"p":86,"l":"Исход · явление восемнадцатое","t":"Плач","d":"Оплакивает братьев и мать над их телами.","c":"","k":false},{"i":2644,"p":95,"l":"Исход · явление девятнадцатое","t":"Вызов Креонту","d":"Отказывается стать женой Гемона, требует похоронить брата и выбирает изгнание с отцом.","c":"Переход от покорности к бунту.","k":true}],"gen":"Антигона"},{"id":"edip","name":"Эдип","role":"Бывший царь Фив","intro":"Слепой старик, которого сыновья держали взаперти.","arc":"Эдип появляется лишь в последней сцене — живое напоминание о проклятии рода. Он вспоминает своё прошлое и, изгнанный Креонтом, уходит из Фив с Антигоной, вспомнив о пророчестве, что умрёт в Колоне.","st":[{"i":2644,"p":95,"l":"Исход · явление девятнадцатое","t":"Выход из дома","d":"Выходит на зов Антигоны, узнаёт о гибели жены и сыновей; Креонт изгоняет его.","c":"","k":false},{"i":2795,"p":100,"l":"Исход · явление двадцатое","t":"Уход","d":"Вспоминает пророчество о Колоне и уходит, опираясь на дочь.","c":"","k":true}],"gen":"Эдип"}]};
